INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 1, 'Match the letters a to h to their sounds', ARRAY['ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.a']::text[], 'The child picks out the letters a, b, c, d, e, f, g and h and the sound each makes (a for apple, b for ball, c for cup), and tells the sound from the letter name. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letter makes this sound","which word starts with this letter","match the letter to the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 1, 'Say the letter-sounds clearly', ARRAY['ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T4_PRONUNCIATION_AND_VO.a', 'ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.b', 'ENGL.G1.READIN.T3_PRE_READING.b', 'ENGL.G1.READIN.T6_WORD_READING.b']::text[], 'The child says each letter-sound short and clean (/b/ not buh, /m/ not muh), keeps l and r and short and long vowels apart, and says words without adding a vowel at the end. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the sound of the letter","say the word after the teacher","say the first sound"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 1, 'Greet people and answer greetings correctly', ARRAY['ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.c']::text[], 'The child uses Good morning, Good afternoon and Good evening at the right time, answers How are you? with I am fine, thank you, and greets elders politely. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what do you say","choose the right greeting","answer the greeting"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE', 'ENGL.G1.READIN.T1_PRE_READING', 'english', 1, 'Sit and hold reading materials the right way', ARRAY['ENGL.G1.READIN.T1_PRE_READING.a', 'ENGL.G1.READIN.T2_PRE_READING.b']::text[], 'The child picks out a good reading posture (back straight, feet on the floor, book on the desk at a comfortable distance, good light) and the book the right way up. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which child is sitting well to read","where should the book be","what is wrong in the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS', 'ENGL.G1.READIN.T1_PRE_READING', 'english', 1, 'Blend letter-sounds to read short words', ARRAY['ENGL.G1.READIN.T1_PRE_READING.b', 'ENGL.G1.READIN.T2_PRE_READING.c', 'ENGL.G1.READIN.T5_PRE_READING.b', 'ENGL.G1.READIN.T7_WORD_READING.b']::text[], 'The child says the sound of each letter left to right and blends them into a word (c-a-t, cat; s-i-t, sit), reading three- and four-letter words with the letters learnt. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read the word","say the sounds, then the word","read the word list"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT', 'ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T', 'english', 1, 'Use am, is and are to greet and introduce', ARRAY['ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.a', 'ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.b']::text[], 'The child picks am, is and are in sentences and uses them to introduce self and others: I am Amina. She is my friend. You are my teacher. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE', 'ENGL.G1.WRITIN.T1_PRE_WRITING', 'english', 1, 'Sit and hold the pencil and book the right way to write', ARRAY['ENGL.G1.WRITIN.T1_PRE_WRITING.a', 'ENGL.G1.WRITIN.T2_PRE_WRITING.a']::text[], 'The child picks out a good writing posture: sitting up, feet on the floor, the book straight in front, the other hand holding the page, the pencil held between thumb and first two fingers. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which child is ready to write","how do we hold the pencil","what is wrong in the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS', 'ENGL.G1.WRITIN.T1_PRE_WRITING', 'english', 1, 'Draw writing patterns with control', ARRAY['ENGL.G1.WRITIN.T1_PRE_WRITING.b', 'ENGL.G1.WRITIN.T2_PRE_WRITING.b']::text[], 'The child traces and copies lines, curves, circles and zigzags from left to right with a light, steady hand, keeping within the lines. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["trace the pattern","copy the pattern","join the dots"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with the sounds of i to p', ARRAY['ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.a']::text[], 'The child hears the sounds /iː/, /ɪ/, /aɪ/, /dʒ/, /k/, /l/, /m/, /n/, /ɒ/, /ɔː/ and /p/ in spoken words and picks out the words that have them (for example sheep, sit, kite, jug, kettle, leg, mat, nest, pot, ball, pen). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 1, 'Say short sentences with new words', ARRAY['ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T4_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.b', 'ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.c']::text[], 'The child says a short sentence of three or more words with a theme word (This is my school. I have a pencil.), not one word. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say a sentence about the picture","tell your partner","answer in a sentence"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS', 'ENGL.G1.READIN.T2_PRE_READING', 'english', 1, 'Tell capital letters from small letters and match them', ARRAY['ENGL.G1.READIN.T2_PRE_READING.a', 'ENGL.G1.WRITIN.T4_HANDWRITING.a', 'ENGL.G1.WRITIN.T5_HANDWRITING.a']::text[], 'The child picks out capital and small letters in a text and matches each pair, including those that look different (A and a, B and b, G and g). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match the capital to the small letter","which is the capital","circle the small letters"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_', 'english', 1, 'Use I, he, she and it', ARRAY['ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.a', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.b']::text[], 'The child picks out I, he, she and it in an oral text and uses them as the subject: he for a boy or man, she for a girl or woman, it for a thing or animal, without repeating the subject. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_', 'english', 1, 'Use do and does', ARRAY['ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.a', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.b']::text[], 'The child picks out do and does in an oral text and uses does with he, she and it and do with I and you, with a plain verb after: She does her homework. Do you like milk? Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 1, 'Match the letters q to z to their sounds', ARRAY['ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.a']::text[], 'The child links q, r, s, t, u, v, w, x, y and z to their sounds (q for queen, v for van, x for box, y for yam) and tells the sound from the letter name. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letter makes this sound","which word starts with this letter","match the letter to the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 1, 'Respond to a one-step instruction', ARRAY['ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T4_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.c']::text[], 'The child carries out a one-step spoken instruction (Stand up. Bring the cup. Put the book under the chair.) by doing it or answering. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["do what the teacher says","Simon says","show me"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES', 'ENGL.G1.READIN.T3_PRE_READING', 'english', 1, 'Name the letters of the alphabet', ARRAY['ENGL.G1.READIN.T3_PRE_READING.a']::text[], 'The child names letters clearly when shown them in any order (q, r, s, t, u, v, w, x, y, z), without singing from a. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["what is this letter called","point to the letter I say","say the letters"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT', 'english', 1, 'Use have and has', ARRAY['ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.a', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.b']::text[], 'The child picks out have and has and uses has with he, she and it and have with I and you: I have a sister. He has a ball. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT', 'english', 1, 'Use me, him, her and it after a verb', ARRAY['ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.a', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.b']::text[], 'The child picks out me, him, her and it in a text and uses them after a verb or a small word like to: Give me the book. I love her. Mama called him. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS', 'ENGL.G1.WRITIN.T3_HANDWRITING', 'english', 1, 'Tell a correctly formed letter from a poorly formed one', ARRAY['ENGL.G1.WRITIN.T3_HANDWRITING.a']::text[], 'The child picks out the correctly formed letter (closed a, s the right way round, tall letters tall) from poorly formed ones in a text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letter is written right","which letter is backwards","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS', 'ENGL.G1.WRITIN.T3_HANDWRITING', 'english', 1, 'Form small and capital letters correctly, writing left to right', ARRAY['ENGL.G1.WRITIN.T3_HANDWRITING.b', 'ENGL.G1.WRITIN.T3_HANDWRITING.c', 'ENGL.G1.WRITIN.T4_HANDWRITING.b', 'ENGL.G1.WRITIN.T4_HANDWRITING.c', 'ENGL.G1.WRITIN.T5_HANDWRITING.b', 'ENGL.G1.WRITIN.T7_SPELLING.b', 'ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.b']::text[], 'The child forms each small letter from the right starting point (round letters from the top, like c), the right size and the right way round, writes capital letters correctly, and writes words left to right. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["write the letter","copy the word","write the letters on the line"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD', 'ENGL.G1.READIN.T4_PRE_READING', 'english', 1, 'Find a letter in words', ARRAY['ENGL.G1.READIN.T4_PRE_READING.a', 'ENGL.G1.WRITIN.T6_SPELLING.a', 'ENGL.G1.WRITIN.T7_SPELLING.a', 'ENGL.G1.WRITIN.T8_SPELLING.a']::text[], 'The child finds a given letter at the start, middle or end of a word, small or capital (m in mat, Amina, ham). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["circle the letter in the word","which word has the letter","how many times"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS', 'ENGL.G1.READIN.T4_PRE_READING', 'english', 1, 'Build words from letters', ARRAY['ENGL.G1.READIN.T4_PRE_READING.b']::text[], 'The child puts letter cards in order to make a short word (m-a-t, t-e-a-m) and finds a missing letter. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["make a word with these letters","which letter is missing","put the letters in order"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES', 'ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS', 'english', 1, 'Make plurals by adding -s or -es', ARRAY['ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.a', 'ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.b']::text[], 'The child adds -s to make most plurals (cup, cups) and -es after s, x, ch and sh (bus, buses; box, boxes; dish, dishes), and keeps the -s after a number (two cups). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["one or many","add -s or -es","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with s, l, i and p', ARRAY['ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.a']::text[], 'The child hears the sounds /s/, /l/, /ɪ/ and /p/ in spoken words and picks out the words that have them (for example sun, leg, pin, pot). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO', 'english', 1, 'Use facial expressions, eye contact and gestures in conversation', ARRAY['ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.c']::text[], 'The child looks at the person speaking, uses a face that fits what is said (a smile for thank you, a sorry face for sorry) and simple gestures (a nod for yes, a wave for goodbye), as is polite at home and school. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["show me with your face","talk with a partner","what does this gesture mean"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND', 'ENGL.G1.READIN.T5_PRE_READING', 'english', 1, 'Match letters to their sounds', ARRAY['ENGL.G1.READIN.T5_PRE_READING.a']::text[], 'The child matches the letters S, L, I and P (and others learnt) to the sounds they make and picks the letter for a sound heard. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letter makes this sound","match the letter to the sound","which sound does it make"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE', 'ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE', 'english', 1, 'Use the present simple for daily activities', ARRAY['ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.a', 'ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.b']::text[], 'The child picks out present simple verbs and uses them for what is done every day, with -s after he, she and it: I wake up at six. She washes her face. We go to school. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O', 'ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with f, n, h and the o sounds', ARRAY['ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T6_WORD_READING.a']::text[], 'The child hears the sounds /f/, /n/, /h/, /ɒ/ (pot) and /ɔː/ (ball) in spoken words and picks out the words that have them (for example fan, nose, hat, dog, door). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS', 'ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT', 'english', 1, 'Use the present continuous for what is happening now', ARRAY['ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.a', 'ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.b']::text[], 'The child names activities going on now in and out of school and uses am, is or are with -ing: I am writing. The children are playing. It is raining. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC', 'ENGL.G1.WRITIN.T6_SPELLING', 'english', 1, 'Spell three- to five-letter words', ARRAY['ENGL.G1.WRITIN.T6_SPELLING.b', 'ENGL.G1.WRITIN.T7_SPELLING.c', 'ENGL.G1.WRITIN.T8_SPELLING.b']::text[], 'The child spells three- to five-letter words with the letters learnt (fan, hen, nut, bag, rug, cow, desk) by writing a letter for each sound in order. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct spelling","fill in the missing letter","write the word"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G', 'ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with b, r, u and g', ARRAY['ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T7_WORD_READING.a']::text[], 'The child hears the sounds /b/, /r/, /ʌ/ (u) and /g/ in spoken words and picks out the words that have them (for example bed, rat, cup, goat). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS', 'ENGL.G1.READIN.T7_WORD_READING', 'english', 1, 'Read common words that cannot be sounded out', ARRAY['ENGL.G1.READIN.T7_WORD_READING.b']::text[], 'The child reads common sight words at a glance (the, is, was, said, are, you, my, of), and does not sound them out letter by letter. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read the word card","find the word","read the sentence"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED', 'ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE', 'english', 1, 'Use the simple past with -ed and -d', ARRAY['ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.a', 'ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.b']::text[], 'The child picks out words ending in -ed and -d in a text and uses them for things that happened: Yesterday I washed my hands. We played football. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS', 'ENGL.G1.WRITIN.T7_SPELLING', 'english', 1, 'Write and choose b, d, p, q, u and n the right way round', ARRAY['ENGL.G1.WRITIN.T7_SPELLING.a']::text[], 'The child writes and picks b, d, p, q, u and n the right way round and up (bag, dog, pen, queen, up, net). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letter is right","fix the word","which word is written right"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with k, d and w', ARRAY['ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T8_FLUENCY.a']::text[], 'The child hears the sounds /k/, /d/ and /w/ in spoken words and picks out the words that have them (for example cat, kite, doll, window). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 1, 'Know and use the words of the theme', ARRAY['ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.c', 'ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.c', 'ENGL.G1.WRITIN.T14_GUIDED_WRITING.a']::text[], 'The child chooses the theme word that fits a picture or sentence (for example eyes, ears, friend, road, chief, share, phone, two, tap) and does not swap it for a word of the same group. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the word that fits","match the word to the picture","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD', 'ENGL.G1.READIN.T8_FLUENCY', 'english', 1, 'Read a short Grade 1 text aloud accurately with few hesitations', ARRAY['ENGL.G1.READIN.T8_FLUENCY.b', 'ENGL.G1.READIN.T9_FLUENCY.b', 'ENGL.G1.READIN.T10_FLUENCY.b', 'ENGL.G1.READIN.T11_FLUENCY.b', 'ENGL.G1.READIN.T12_FLUENCY.b', 'ENGL.G1.READIN.T14_FLUENCY.b', 'ENGL.G1.READIN.T15_FLUENCY.b']::text[], 'The child reads a few short sentences aloud, blending new words and reading sight words at a glance, with few long stops, pointing under the words. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","read the sentences","read the page"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING', 'ENGL.G1.READIN.T8_FLUENCY', 'english', 1, 'Show the right feeling when reading aloud', ARRAY['ENGL.G1.READIN.T8_FLUENCY.c']::text[], 'The child lets the voice show a feeling in the text (happy, sad, surprised), lifts the voice for a question and stops at full stops. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read it happily, read it sadly","read like the character","read the question"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES', 'ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_', 'english', 1, 'Use this, that, these and those', ARRAY['ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.a', 'ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.b']::text[], 'The child picks out this, that, these and those and uses this and these for things near, that and those for things far, with one or many: This is my nose. Those are your shoes. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["this or that","these or those","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S', 'ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with k, y, l and s', ARRAY['ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T9_FLUENCY.a']::text[], 'The child hears the sounds /k/, /j/ (y as in yes), /l/ and /s/ in spoken words and picks out the words that have them (for example cup, yes, lamp, sit). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS', 'ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO', 'english', 1, 'Name people, things and places (common and proper nouns)', ARRAY['ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.a', 'ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.b']::text[], 'The child picks out naming words for people, things and places, tells a general name (girl, town) from a special name (Wanjiru, Nakuru), and uses both in short sentences. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word names a person, thing or place","which name needs a capital","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP', 'ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_', 'english', 1, 'Use a capital letter to start and a full stop to end a sentence', ARRAY['ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.a', 'ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.c']::text[], 'The child picks out capital letters, small letters and full stops in a text, starts every sentence with a capital and ends it with a full stop. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which sentence is right","add the full stop","which word needs a capital"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS', 'ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with the short a and the long vowel sounds', ARRAY['ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T10_FLUENCY.a']::text[], 'The child hears the sounds /æ/ (cat), /ɔː/ (chalk), /iː/ (chief), /uː/ (school), /ɔɪ/ (boy) and /eɪ/ (day) in spoken words and picks out the words that have them (for example cat, door, tree, food, toy, play). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS', 'ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_', 'english', 1, 'Use in, on, under, between, behind, in front of, inside and outside', ARRAY['ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.a', 'ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.b']::text[], 'The child picks out the position words in a text and uses them in short sentences about safety: The knife is in the drawer. Stand behind the line. Play outside. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where is it","choose the word","describe the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK', 'ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_', 'english', 1, 'Use a capital letter and a question mark for a question', ARRAY['ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.a', 'ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.b']::text[], 'The child picks out question marks and capitals in a text and writes a question that starts with a capital and ends with a question mark. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which mark goes at the end","correct the question","is it a question"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH', 'ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with sh, ch and th', ARRAY['ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T11_FLUENCY.a']::text[], 'The child hears the sounds /ʃ/ (sh), /tʃ/ (ch) and the two th sounds /θ/ (thin) and /ð/ (this) in spoken words and picks out the words that have them (for example share, chair, thank, this). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.PREDICT', 'ENGL.G1.READIN.T11_COMPREHENSION', 'english', 1, 'Predict what a story will be about from the title and pictures', ARRAY['ENGL.G1.READIN.T11_COMPREHENSION.a', 'ENGL.G1.READIN.T12_COMPREHENSION.a', 'ENGL.G1.READIN.T13_COMPREHENSION.a', 'ENGL.G1.READIN.T14_COMPREHENSION.a', 'ENGL.G1.READIN.T15_COMPREHENSION.b']::text[], 'The child looks at the title and pictures and says what the story will be about or what will happen next, and why. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what will happen","what is the story about","which picture comes next"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS', 'ENGL.G1.READIN.T11_COMPREHENSION', 'english', 1, 'Answer simple direct and indirect questions on a text', ARRAY['ENGL.G1.READIN.T11_COMPREHENSION.b', 'ENGL.G1.READIN.T12_COMPREHENSION.c', 'ENGL.G1.READIN.T13_COMPREHENSION.c', 'ENGL.G1.READIN.T14_COMPREHENSION.c', 'ENGL.G1.READIN.T15_COMPREHENSION.c']::text[], 'The child answers who, what and where questions from a short text or picture story, and simple how did he feel questions from clues (he cried: sad). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["answer the question","choose the answer","how does the character feel"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES', 'ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T', 'english', 1, 'Use describing words for people, places and things', ARRAY['ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.a', 'ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.b', 'ENGL.G1.WRITIN.T15_GUIDED_WRITING.a']::text[], 'The child names describing words (big, small, tall, kind, clean, red) and uses them before the noun to talk about people, places and things: a tall chief, a clean market. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word describes","choose the describing word","describe the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING', 'english', 1, 'Say what a picture is about', ARRAY['ENGL.G1.WRITIN.T11_GUIDED_WRITING.a', 'ENGL.G1.WRITIN.T12_GUIDED_WRITING.a']::text[], 'The child says what a picture shows and what is happening in it (The chief is talking to the people), not just one object in it. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what is the picture about","what is happening","which sentence matches the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING', 'english', 1, 'Write simple sentences with short words', ARRAY['ENGL.G1.WRITIN.T11_GUIDED_WRITING.b', 'ENGL.G1.WRITIN.T14_GUIDED_WRITING.b']::text[], 'The child writes a simple sentence of his or her own with four- to six-letter words, a capital letter, spaces between words and a full stop. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a sentence about","write a sentence with the word","write about the picture"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR', 'ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with e, ee and air', ARRAY['ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T12_FLUENCY.a', 'ENGL.G1.READIN.T12_COMPREHENSION.b']::text[], 'The child hears the sounds /e/ (bed), /iː/ (see) and /eə/ (chair, share) in spoken words and picks out the words that have them (for example bed, sleep, chair). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES', 'ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H', 'english', 1, 'Use my, our, her, his, their and its', ARRAY['ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.a', 'ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.b']::text[], 'The child picks out possessives in a text and uses them to show who owns something: my bag, our school, her pen, his cup, their house, its tail. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","say it the right way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS', 'ENGL.G1.WRITIN.T12_GUIDED_WRITING', 'english', 1, 'Fill gaps in simple sentences', ARRAY['ENGL.G1.WRITIN.T12_GUIDED_WRITING.b', 'ENGL.G1.WRITIN.T13_GUIDED_WRITING.a']::text[], 'The child chooses the word that fits the gap in meaning and form (We live ___ together: in peace) by reading the whole sentence. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the word for the gap","fill the gap","which word fits"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY', 'ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with the short oo and long a sounds', ARRAY['ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.a']::text[], 'The child hears the sounds /ʊ/ (book, put) and /eɪ/ (play, game) in spoken words and picks out the words that have them (for example book, foot, play, take). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT', 'ENGL.G1.READIN.T13_COMPREHENSION', 'english', 1, 'Guess the meaning of a new word from the sentence and picture', ARRAY['ENGL.G1.READIN.T13_COMPREHENSION.b']::text[], 'The child uses the picture and the words around a new word to say what it means. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what does the word mean","which picture shows the word","which clue helps"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS', 'ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT', 'english', 1, 'Ask and answer yes or no questions with can, may and will', ARRAY['ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.a', 'ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.b']::text[], 'The child picks out yes or no questions with can, may and will and answers in full: Can you use a phone? Yes, I can. May I go out? Yes, you may. Will it rain? No, it will not. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["answer the question","which answer is right","ask the question"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'ENGL.G1.WRITIN.T13_GUIDED_WRITING', 'english', 1, 'Rearrange words to make a simple sentence', ARRAY['ENGL.G1.WRITIN.T13_GUIDED_WRITING.b']::text[], 'The child rearranges three to five jumbled words into a sentence that makes sense, starting with the word with a capital letter. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the words in order","which sentence is right","make a sentence"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG', 'ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and pick out words with j, s and ng', ARRAY['ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T14_FLUENCY.a', 'ENGL.G1.READIN.T14_COMPREHENSION.b']::text[], 'The child hears the sounds /dʒ/ (jug, orange), /s/ and /ŋ/ (sing, ring) in spoken words and picks out the words that have them (for example jump, six, string). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE', 'ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE', 'english', 1, 'Use adverbs of place: here, there, inside, outside, up, down, near, far', ARRAY['ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.a', 'ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.b']::text[], 'The child picks out adverbs of place in sentences and uses them to say where things and people are: Come here. The goats are outside. The shop is far. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where","choose the word","describe where it is"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R', 'ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO', 'english', 1, 'Hear and tell apart words with l, s and r', ARRAY['ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.a', 'ENGL.G1.READIN.T15_FLUENCY.a', 'ENGL.G1.READIN.T15_COMPREHENSION.a']::text[], 'The child hears the sounds /l/, /s/ and /r/, telling l from r in spoken words and picks out the words that have them (for example light, sun, rain). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word starts with the sound","point to the picture with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS', 'ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR', 'english', 1, 'Use words that show surprise', ARRAY['ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.a', 'ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.b']::text[], 'The child picks out words of surprise (Oh! Wow! What!) in a text and uses them in short sentences with an exclamation mark. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word shows surprise","complete with the word","choose the right word"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES', 'ENGL.G1.WRITIN.T15_GUIDED_WRITING', 'english', 1, 'Write short sentences with describing words', ARRAY['ENGL.G1.WRITIN.T15_GUIDED_WRITING.b']::text[], 'The child writes a short sentence that uses a describing word before the noun (The tap has clean water. I have a green tree.). Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["describe the picture","write a sentence with a describing word","tell me about it"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
