INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H.M1_LH_NAME_FOR_SOUND', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H', 'Gives the letter name instead of its sound.', '{"question":"What sound does b make?","wrong_answer":"bee","correct_answer":"/b/"}'::jsonb, 'Letter names are learnt first (often in the alphabet song), and the child thinks the name is the sound.', 'Offer "bee" beside "/b/" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The name is bee; the sound is a short /b/, as in ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H.M1_LH_B_D', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H', 'Mixes b and d.', '{"question":"Which letter does \"dog\" start with: b or d?","wrong_answer":"b","correct_answer":"d"}'::jsonb, 'B and d are the same shape turned round.', 'Offer "b" beside "d" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make a bed with your fists: b on the left, d on the right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H.M1_LH_C_S', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H', 'Thinks c says /s/ because its name is see.', '{"question":"Which word starts with the letter c: cup, sun, pen?","wrong_answer":"sun","correct_answer":"cup"}'::jsonb, 'The letter name is taken as the sound.', 'Offer "sun" beside "cup" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'C says /k/ in cup, cat and cow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H.M1_LH_E_I', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.LETTERS_A_H', 'Hears e and i as the same sound.', '{"question":"Which word starts with e: egg, ink, ant?","wrong_answer":"ink","correct_answer":"egg"}'::jsonb, 'Many home languages have one sound between English e and i.', 'Offer "ink" beside "egg" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'E: mouth a little open, egg. I: smile, ink.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS.M1_SLS_NAME', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS', 'Says the letter name instead of the sound.', '{"question":"Say the sound of m.","wrong_answer":"em","correct_answer":"/m/"}'::jsonb, 'Letter names are learnt first.', 'Offer "em" beside "/m/" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The sound is mmm, short and clean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS.M1_SLS_UH', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS', 'Adds uh to every consonant.', '{"question":"Say the sound of b.","wrong_answer":"buh","correct_answer":"/b/ (short)"}'::jsonb, 'Consonants are said with a vowel, as in home-language syllables.', 'Offer "buh" beside "/b/ (short)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Clip it short: b, not buh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS.M1_SLS_L_R', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS', 'Says l for r or r for l.', '{"question":"Say: red lorry","wrong_answer":"led rolly","correct_answer":"red lorry"}'::jsonb, 'L and r merged.', 'Offer "led rolly" beside "red lorry" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up for l, curled for r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS.M1_SLS_END_VOWEL', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.SAY_LETTER_SOUNDS', 'Adds a vowel at the end of a word.', '{"question":"Say: book","wrong_answer":"booki","correct_answer":"book"}'::jsonb, 'Kiswahili words end in a vowel (buku).', 'Offer "booki" beside "book" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stop at k.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS.M1_GR_TIME', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS', 'Uses a greeting for the wrong time of day.', '{"question":"You meet your teacher at four in the afternoon. You say ...","wrong_answer":"Good morning","correct_answer":"Good afternoon"}'::jsonb, 'Good morning is the greeting learnt first and used all day.', 'Offer "Good morning" beside "Good afternoon" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Morning before lunch, afternoon after lunch, evening at dusk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS.M1_GR_REPLY_FINE', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS', 'Answers Good morning with Fine.', '{"question":"Teacher: \"Good morning, Amina.\"","wrong_answer":"Fine.","correct_answer":"Good morning, teacher."}'::jsonb, 'The child expects every greeting to ask how you are.', 'Offer "Fine." beside "Good morning, teacher." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Answer a greeting with the same greeting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS.M1_GR_NIGHT', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS', 'Uses Good night as a greeting on arriving.', '{"question":"Your uncle visits at eight in the evening. You say ...","wrong_answer":"Good night","correct_answer":"Good evening"}'::jsonb, 'Good night sounds like the evening greeting.', 'Offer "Good night" beside "Good evening" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Good night is for going to bed or leaving.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS.M1_GR_ELDER_HI', 'ENGL.G1.LISTEN.T1_PRONUNCIATION_AND_VO.GREETINGS', 'Greets an elder with Hi.', '{"question":"You meet the head teacher. You say ...","wrong_answer":"Hi!","correct_answer":"Good morning, madam."}'::jsonb, 'Hi is heard among friends and on television.', 'Offer "Hi!" beside "Good morning, madam." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Elders: Good morning, sir or madam.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE.M1_RP_SLOUCH', 'ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE', 'Thinks lying on the desk is a good way to read.', '{"question":"Which child is sitting well to read?","wrong_answer":"the child with the head on the desk","correct_answer":"the child sitting up with feet on the floor"}'::jsonb, 'The child copies how he or she rests.', 'Offer "the child with the head on the desk" beside "the child sitting up with feet on the floor" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Back straight, feet on the floor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE.M1_RP_TOO_CLOSE', 'ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE', 'Holds the book right up to the eyes.', '{"question":"How far should the book be?","wrong_answer":"touching my nose","correct_answer":"about the length from elbow to hand"}'::jsonb, 'Close feels like looking hard.', 'Offer "touching my nose" beside "about the length from elbow to hand" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Elbow to hand away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE.M1_RP_UPSIDE', 'ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE', 'Holds the book upside down or back to front.', '{"question":"Which book is the right way up?","wrong_answer":"the one with the pictures upside down","correct_answer":"the one with the picture of the people standing up"}'::jsonb, 'Book handling is new at home.', 'Offer "the one with the pictures upside down" beside "the one with the picture of the people standing up" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'People in the pictures stand up; start at the front.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE.M1_RP_DARK', 'ENGL.G1.READIN.T1_PRE_READING.READING_POSTURE', 'Chooses a dark corner to read.', '{"question":"Where is the best place to read?","wrong_answer":"in the dark corner","correct_answer":"near the window, in good light"}'::jsonb, 'A quiet corner seems good even if dark.', 'Offer "in the dark corner" beside "near the window, in good light" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read where there is light.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS.M1_DW_NO_BLEND', 'ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS', 'Says the sounds but cannot join them into the word.', '{"question":"Read: c-a-t","wrong_answer":"says c, a, t, then \"cup\"","correct_answer":"cat"}'::jsonb, 'Each sound is said alone and the child does not push them together.', 'Offer "says c, a, t, then "cup"" beside "cat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say the sounds faster and faster until they join: c-a-t, cat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS.M1_DW_PICTURE', 'ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS', 'Says the word the picture shows instead of reading it.', '{"question":"Read the word under a picture of a cat: kitten","wrong_answer":"cat","correct_answer":"kitten"}'::jsonb, 'Sight-word and picture guessing take the place of reading.', 'Offer "cat" beside "kitten" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Cover the picture: read the letters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS.M1_DW_B_D', 'ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS', 'Reads b as d or d as b.', '{"question":"Read: bad","wrong_answer":"dad","correct_answer":"bad"}'::jsonb, 'B and d are mirror shapes.', 'Offer "dad" beside "bad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make a bed with your fists.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS.M1_DW_RIGHT_LEFT', 'ENGL.G1.READIN.T1_PRE_READING.DECODE_WORDS', 'Reads the letters from right to left.', '{"question":"Read: pit","wrong_answer":"tip","correct_answer":"pit"}'::jsonb, 'Left to right is not yet fixed.', 'Offer "tip" beside "pit" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start at the green dot on the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT.M1_BE_I_IS', 'ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT', 'Uses is with I.', '{"question":"I ... Amina.","wrong_answer":"is","correct_answer":"am"}'::jsonb, 'Is is heard most often and used for everyone.', 'Offer "is" beside "am" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I am. He is. You are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT.M1_BE_HE_ARE', 'ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT', 'Uses are with he or she.', '{"question":"She ... my sister.","wrong_answer":"are","correct_answer":"is"}'::jsonb, 'Are is used for any person.', 'Offer "are" beside "is" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One person, he or she: is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT.M1_BE_DROP', 'ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT', 'Leaves out am, is or are.', '{"question":"Introduce yourself: I ... Juma.","wrong_answer":"(nothing): I Juma.","correct_answer":"am"}'::jsonb, 'The small word is not heard in speech.', 'Offer "(nothing): I Juma." beside "am" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I am Juma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT.M1_BE_YOU_IS', 'ENGL.G1.LANGUA.T1_VERB_TO_BE_PRESENT_T.VERB_BE_PRESENT', 'Uses is with you.', '{"question":"You ... my friend.","wrong_answer":"is","correct_answer":"are"}'::jsonb, 'You is treated like he.', 'Offer "is" beside "are" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'You are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE.M1_WP_SLOUCH', 'ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE', 'Thinks lying over the desk is fine for writing.', '{"question":"Which child is ready to write?","wrong_answer":"the child lying over the desk","correct_answer":"the child sitting up with feet on the floor"}'::jsonb, 'The child copies how he or she rests.', 'Offer "the child lying over the desk" beside "the child sitting up with feet on the floor" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sit up: back straight, feet down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE.M1_WP_FIST', 'ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE', 'Holds the pencil in a fist.', '{"question":"Which picture shows the right way to hold a pencil?","wrong_answer":"the pencil in a closed fist","correct_answer":"the pencil between thumb and two fingers"}'::jsonb, 'A fist grip is how a young child first holds a stick or spoon.', 'Offer "the pencil in a closed fist" beside "the pencil between thumb and two fingers" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pinch with thumb and finger, rest it on the middle finger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE.M1_WP_NO_HOLD', 'ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE', 'Does not hold the page with the other hand.', '{"question":"What does your other hand do when you write?","wrong_answer":"stays on my lap","correct_answer":"holds the book still"}'::jsonb, 'The child does not notice the page sliding.', 'Offer "stays on my lap" beside "holds the book still" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Your helper hand holds the book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE.M1_WP_FACE_ON_BOOK', 'ENGL.G1.WRITIN.T1_PRE_WRITING.WRITING_POSTURE', 'Puts the face right on the book.', '{"question":"How close should your eyes be to the book?","wrong_answer":"touching the page","correct_answer":"about a ruler away"}'::jsonb, 'Close is thought to be careful.', 'Offer "touching the page" beside "about a ruler away" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sit back a little.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS.M1_PW_RIGHT_LEFT', 'ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS', 'Draws patterns from right to left.', '{"question":"Trace the zigzag.","wrong_answer":"starts on the right","correct_answer":"starts on the left and goes right"}'::jsonb, 'The direction of writing is not yet fixed.', 'Offer "starts on the right" beside "starts on the left and goes right" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start at the green dot on the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS.M1_PW_PRESS', 'ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS', 'Presses so hard the page tears.', '{"question":"Trace the circle.","wrong_answer":"deep grooves, torn page","correct_answer":"a light, smooth line"}'::jsonb, 'A tight grip from effort.', 'Offer "deep grooves, torn page" beside "a light, smooth line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hold the pencil lightly; let it glide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS.M1_PW_LIFT', 'ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS', 'Lifts the pencil many times in one line.', '{"question":"Trace the wavy line.","wrong_answer":"many short broken strokes","correct_answer":"one smooth line"}'::jsonb, 'Control is still weak and the child stops often.', 'Offer "many short broken strokes" beside "one smooth line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the pencil on the paper to the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS.M1_PW_OUTSIDE', 'ENGL.G1.WRITIN.T1_PRE_WRITING.PRE_WRITING_PATTERNS', 'Goes far outside the lines.', '{"question":"Trace between the two lines.","wrong_answer":"lines all over the page","correct_answer":"a line between the lines"}'::jsonb, 'Speed matters more to the child than control.', 'Offer "lines all over the page" beside "a line between the lines" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Slow down and watch the lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P.M1_IP_SHEEP_SHIP', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P', 'Hears the long ee and short i as the same.', '{"question":"The teacher says \"sheep\". Sheep or ship?","wrong_answer":"ship","correct_answer":"sheep"}'::jsonb, 'Five-vowel home languages have one i sound.', 'Offer "ship" beside "sheep" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sheep is long, with a smile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P.M1_IP_I_NAME', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P', 'Hears short i as the letter name i (eye).', '{"question":"Which word has the sound in \"sit\": kite, pin, pie?","wrong_answer":"kite","correct_answer":"pin"}'::jsonb, 'The letter name is taken as the sound.', 'Offer "kite" beside "pin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short i: quick, as in sit and pin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P.M1_IP_M_N', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P', 'Mixes m and n.', '{"question":"The teacher says \"mat\". Mat or nat?","wrong_answer":"nat","correct_answer":"mat"}'::jsonb, 'Both are nose sounds.', 'Offer "nat" beside "mat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'For m the lips close: mmm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P.M1_IP_P_B', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SOUNDS_I_P', 'Mixes p and b.', '{"question":"The teacher says \"pen\". Pen or Ben?","wrong_answer":"Ben","correct_answer":"pen"}'::jsonb, 'P and b are kept apart only by voice.', 'Offer "Ben" beside "pen" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'P puffs air; feel it on your hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES.M1_SS_ONE_WORD', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES', 'Answers with one word.', '{"question":"What do you see in the picture?","wrong_answer":"Book.","correct_answer":"I see a book."}'::jsonb, 'One word names the thing.', 'Offer "Book." beside "I see a book." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with I see ...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES.M1_SS_HOME_WORD', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES', 'Mixes in a home-language word.', '{"question":"Tell me about your family.","wrong_answer":"I have mama na baba.","correct_answer":"I have a mother and a father."}'::jsonb, 'The home word comes first to mind.', 'Offer "I have mama na baba." beside "I have a mother and a father." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say it all in English.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES.M1_SS_NO_VERB', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES', 'Leaves out the verb.', '{"question":"Tell me what you have.","wrong_answer":"Me pencil.","correct_answer":"I have a pencil."}'::jsonb, 'Early speech names things without a verb.', 'Offer "Me pencil." beside "I have a pencil." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I have a ...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES.M1_SS_ECHO', 'ENGL.G1.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_SENTENCES', 'Repeats the question.', '{"question":"Teacher: \"What is your name?\"","wrong_answer":"What is your name.","correct_answer":"My name is Otieno."}'::jsonb, 'The child repeats to buy time.', 'Offer "What is your name." beside "My name is Otieno." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with My name is ...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS.M1_CS_NOT_PAIRS', 'ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS', 'Does not see that a capital and small letter are the same letter.', '{"question":"Match: A to a, b, d?","wrong_answer":"b","correct_answer":"a"}'::jsonb, 'Some pairs look very different.', 'Offer "b" beside "a" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A and a are the same letter: same sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS.M1_CS_B_D', 'ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS', 'Matches B to d.', '{"question":"Which small letter goes with B?","wrong_answer":"d","correct_answer":"b"}'::jsonb, 'B and d are mirror shapes.', 'Offer "d" beside "b" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'B and b both have the belly on the right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS.M1_CS_BIG_SMALL', 'ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS', 'Thinks a small letter written big is a capital.', '{"question":"Is a big \"e\" written large the capital E?","wrong_answer":"yes","correct_answer":"no, capital E has straight lines"}'::jsonb, 'Capital is taken to mean big.', 'Offer "yes" beside "no, capital E has straight lines" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Capitals have their own shapes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS.M1_CS_P_Q', 'ENGL.G1.READIN.T2_PRE_READING.CAPITAL_SMALL_LETTERS', 'Matches small p or q to the wrong capital.', '{"question":"Which small letter goes with Q?","wrong_answer":"p","correct_answer":"q"}'::jsonb, 'P and q are mirror shapes.', 'Offer "p" beside "q" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Q has its tail on the right; small q too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG.M1_SP_HE_SHE', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG', 'Uses he for a girl or she for a boy.', '{"question":"This is Amina. ... is my sister.","wrong_answer":"He","correct_answer":"She"}'::jsonb, 'Kiswahili yeye means he or she.', 'Offer "He" beside "She" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A girl: she. A boy: he.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG.M1_SP_ME_SUBJECT', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG', 'Uses me as the subject.', '{"question":"... go to school.","wrong_answer":"Me","correct_answer":"I"}'::jsonb, 'Me is heard in speech (Me, I like ...).', 'Offer "Me" beside "I" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'At the start: I.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG.M1_SP_DOUBLE', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG', 'Repeats the subject.', '{"question":"Say: Juma plays.","wrong_answer":"Juma he plays.","correct_answer":"Juma plays."}'::jsonb, 'Spoken Kenyan English marks the subject twice.', 'Offer "Juma he plays." beside "Juma plays." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One subject.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG.M1_SP_IT_PERSON', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.SUBJECT_PRONOUNS_SG', 'Uses it for a person.', '{"question":"This is my grandmother. ... is kind.","wrong_answer":"It","correct_answer":"She"}'::jsonb, 'It is learnt as a word for anything.', 'Offer "It" beside "She" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'People: he or she. Things: it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES.M1_DD_HE_DO', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES', 'Uses do with he or she.', '{"question":"Baba ... the cooking on Sunday.","wrong_answer":"do","correct_answer":"does"}'::jsonb, 'The -es is not linked to he and she.', 'Offer "do" beside "does" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'He, she, it: does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES.M1_DD_I_DOES', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES', 'Uses does with I.', '{"question":"I ... my homework.","wrong_answer":"does","correct_answer":"do"}'::jsonb, 'Does is over-used.', 'Offer "does" beside "do" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I: do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES.M1_DD_DOES_S', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES', 'Adds -s to the verb after does.', '{"question":"Does she ... milk? (like)","wrong_answer":"likes","correct_answer":"like"}'::jsonb, 'The -s is shown twice.', 'Offer "likes" beside "like" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After does, the verb is plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES.M1_DD_NOT_NO_DO', 'ENGL.G1.LANGUA.T2_VERBS_TO_DO_PRESENT_.DO_DOES', 'Says not without do.', '{"question":"I ... like rain. (negative)","wrong_answer":"not","correct_answer":"do not"}'::jsonb, 'Word for word from Kiswahili (sipendi).', 'Offer "not" beside "do not" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I do not like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z.M1_QZ_NAME_FOR_SOUND', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z', 'Gives the letter name instead of its sound.', '{"question":"What sound does v make?","wrong_answer":"vee","correct_answer":"/v/"}'::jsonb, 'Letter names are learnt first.', 'Offer "vee" beside "/v/" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The sound is short: /v/, as in van.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z.M1_QZ_V_B', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z', 'Says or hears v as b or f.', '{"question":"The teacher says \"van\". Which letter does it start with: v or b?","wrong_answer":"b","correct_answer":"v"}'::jsonb, 'Some home languages have no /v/, so b or f is used.', 'Offer "b" beside "v" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'V: teeth on the lip and buzz.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z.M1_QZ_X_START', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z', 'Expects x to say its name eks at the start of words.', '{"question":"Where do you hear the x sound in \"box\": start or end?","wrong_answer":"start","correct_answer":"end"}'::jsonb, 'X is learnt as a name and is usually met at the end of a word.', 'Offer "start" beside "end" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'X says ks at the end: box, six.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z.M1_QZ_R_L', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.LETTERS_Q_Z', 'Hears r as l.', '{"question":"The teacher says \"rat\". Which letter does it start with: r or l?","wrong_answer":"l","correct_answer":"r"}'::jsonb, 'L and r are one sound in some home languages.', 'Offer "l" beside "r" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'R: curl the tongue back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP.M1_FO_COPY', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP', 'Copies a classmate instead of listening.', '{"question":"Touch your nose.","wrong_answer":"touches the ear a friend touched","correct_answer":"touches the nose"}'::jsonb, 'The child relies on others when unsure.', 'Offer "touches the ear a friend touched" beside "touches the nose" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen with your eyes closed, then do it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP.M1_FO_HALF', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP', 'Does only part of the instruction.', '{"question":"Put the book on the table.","wrong_answer":"picks up the book and holds it","correct_answer":"puts the book on the table"}'::jsonb, 'The child acts on the first words heard.', 'Offer "picks up the book and holds it" beside "puts the book on the table" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen to the end before you move.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP.M1_FO_POSITION', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP', 'Mixes position words.', '{"question":"Put the ball under the chair.","wrong_answer":"puts it on the chair","correct_answer":"puts it under the chair"}'::jsonb, 'Position words are new in English.', 'Offer "puts it on the chair" beside "puts it under the chair" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Under is below.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP.M1_FO_OPEN_CLOSE', 'ENGL.G1.LISTEN.T3_PRONUNCIATION_AND_VO.FOLLOW_ONE_STEP', 'Does the opposite action.', '{"question":"Close the door.","wrong_answer":"opens the door","correct_answer":"closes the door"}'::jsonb, 'Opposite pairs are learnt together and mixed.', 'Offer "opens the door" beside "closes the door" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Close: shut it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES.M1_LN_SOUND', 'ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES', 'Gives the sound when asked for the name.', '{"question":"What is this letter called? (s)","wrong_answer":"/s/","correct_answer":"ess"}'::jsonb, 'Sounds and names are learnt together.', 'Offer "/s/" beside "ess" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Name: ess. Sound: /s/.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES.M1_LN_SONG', 'ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES', 'Has to sing the alphabet from a to find a letter''s name.', '{"question":"What is this letter called? (t)","wrong_answer":"sings a, b, c ... until t","correct_answer":"tee"}'::jsonb, 'The names are known only as a song.', 'Offer "sings a, b, c ... until t" beside "tee" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Know each letter on its own: tee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES.M1_LN_V_B', 'ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES', 'Calls v bee.', '{"question":"What is this letter called? (v)","wrong_answer":"bee","correct_answer":"vee"}'::jsonb, 'Some home languages have no /v/.', 'Offer "bee" beside "vee" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'V: teeth on lip, vee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES.M1_LN_U_W', 'ENGL.G1.READIN.T3_PRE_READING.LETTER_NAMES', 'Points to w when asked for u (you).', '{"question":"Point to the letter \"you\".","wrong_answer":"w (double-u)","correct_answer":"u"}'::jsonb, 'Double-u contains the word you.', 'Offer "w (double-u)" beside "u" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'U is one cup; w is two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS.M1_HH_SHE_HAVE', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS', 'Uses have with he or she.', '{"question":"Amina ... a doll.","wrong_answer":"have","correct_answer":"has"}'::jsonb, 'Have is learnt first.', 'Offer "have" beside "has" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'He, she: has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS.M1_HH_I_HAS', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS', 'Uses has with I.', '{"question":"I ... a brother.","wrong_answer":"has","correct_answer":"have"}'::jsonb, 'Has is over-used.', 'Offer "has" beside "have" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I: have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS.M1_HH_HAVING', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS', 'Says am having for have.', '{"question":"I ... two sisters.","wrong_answer":"am having","correct_answer":"have"}'::jsonb, 'Common Kenyan English.', 'Offer "am having" beside "have" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS.M1_HH_WITH', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.HAVE_HAS', 'Says is with for has.', '{"question":"Juma ... a pencil.","wrong_answer":"is with","correct_answer":"has"}'::jsonb, 'Kiswahili yuko na (is with) is said word for word.', 'Offer "is with" beside "has" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Juma has a pencil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG.M1_OP_I_ME', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG', 'Uses I after a verb.', '{"question":"Give ... the ball.","wrong_answer":"I","correct_answer":"me"}'::jsonb, 'I and me mean the same person.', 'Offer "I" beside "me" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After give: me.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG.M1_OP_HE_HIM', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG', 'Uses he after a verb.', '{"question":"Mama called ...","wrong_answer":"he","correct_answer":"him"}'::jsonb, 'He and him mean the same person.', 'Offer "he" beside "him" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After the verb: him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG.M1_OP_HIM_HER', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG', 'Uses him for a girl.', '{"question":"I love my sister. I hug ...","wrong_answer":"him","correct_answer":"her"}'::jsonb, 'Kiswahili -m- (mpenda) serves both.', 'Offer "him" beside "her" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A girl: her.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG.M1_OP_SHE_HER', 'ENGL.G1.LANGUA.T3_VERB_TO_HAVE_PRESENT.OBJECT_PRONOUNS_SG', 'Uses she after a verb.', '{"question":"I helped ...","wrong_answer":"she","correct_answer":"her"}'::jsonb, 'She and her are mixed.', 'Offer "she" beside "her" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After the verb: her.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS.M1_FL_BACKWARDS', 'ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS', 'Accepts a backwards letter as right.', '{"question":"Which s is written right?","wrong_answer":"a backwards s","correct_answer":"s"}'::jsonb, 'Mirror letters look the same to a young child.', 'Offer "a backwards s" beside "s" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S starts at the top like a c.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS.M1_FL_B_D', 'ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS', 'Takes d for b.', '{"question":"Which is the letter b?","wrong_answer":"d","correct_answer":"b"}'::jsonb, 'Mirror shapes.', 'Offer "d" beside "b" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make a bed with your fists.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS.M1_FL_SIZE', 'ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS', 'Accepts a short letter written tall.', '{"question":"Which \"a\" is the right size?","wrong_answer":"a tall a reaching the top line","correct_answer":"a short a"}'::jsonb, 'Size is not yet noticed.', 'Offer "a tall a reaching the top line" beside "a short a" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short letters fill half the space.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS.M1_FL_OPEN', 'ENGL.G1.WRITIN.T3_HANDWRITING.FORMED_LETTERS', 'Accepts an open a or o.', '{"question":"Which a is written right?","wrong_answer":"an a like a u","correct_answer":"a closed a"}'::jsonb, 'The child starts round letters at the bottom.', 'Offer "an a like a u" beside "a closed a" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Round letters close at the top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS.M1_FM_BOTTOM_START', 'ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS', 'Starts round letters at the bottom.', '{"question":"Write the letter a.","wrong_answer":"starts at the bottom, a looks like u","correct_answer":"starts at the top like c, then down"}'::jsonb, 'No one has shown the starting point.', 'Offer "starts at the bottom, a looks like u" beside "starts at the top like c, then down" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start at the top, go round like c.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS.M1_FM_REVERSE', 'ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS', 'Writes s, z or j backwards.', '{"question":"Write: sun","wrong_answer":"sun with a backwards s","correct_answer":"sun"}'::jsonb, 'Mirror letters are still mixed at six.', 'Offer "sun with a backwards s" beside "sun" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S starts like c at the top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS.M1_FM_CAPS_MIX', 'ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS', 'Mixes capitals into a word.', '{"question":"Write: bat","wrong_answer":"bAt","correct_answer":"bat"}'::jsonb, 'Capital A is easier to form.', 'Offer "bAt" beside "bat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Small letters inside a word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS.M1_FM_RIGHT_LEFT', 'ENGL.G1.WRITIN.T3_HANDWRITING.FORM_LETTERS', 'Writes the word from right to left.', '{"question":"Write: mat","wrong_answer":"tam","correct_answer":"mat"}'::jsonb, 'Left to right is not yet fixed.', 'Offer "tam" beside "mat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start at the margin on the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD.M1_LW_FIRST', 'ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD', 'Looks only at the first letter.', '{"question":"Does \"ham\" have an m?","wrong_answer":"no","correct_answer":"yes, at the end"}'::jsonb, 'Only first letters have been practised.', 'Offer "no" beside "yes, at the end" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at every letter, left to right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD.M1_LW_M_N', 'ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD', 'Takes n for m or h for n.', '{"question":"Circle the m in \"man\".","wrong_answer":"circles the n","correct_answer":"circles the m"}'::jsonb, 'The shapes are close.', 'Offer "circles the n" beside "circles the m" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'M has two humps; n has one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD.M1_LW_CAPITAL', 'ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD', 'Misses the letter when it is a capital.', '{"question":"How many a''s in \"Amina\"?","wrong_answer":"1","correct_answer":"2"}'::jsonb, 'A and a are not seen as the same.', 'Offer "1" beside "2" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Capital A is an a too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD.M1_LW_B_D', 'ENGL.G1.READIN.T4_PRE_READING.LETTER_IN_WORD', 'Takes d for b.', '{"question":"Circle the b in \"bed\".","wrong_answer":"circles the d","correct_answer":"circles the b"}'::jsonb, 'Mirror shapes.', 'Offer "circles the d" beside "circles the b" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make the bed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS.M1_BW_ORDER', 'ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS', 'Puts the letters in the wrong order.', '{"question":"Make \"mat\" with m, a, t.","wrong_answer":"tam","correct_answer":"mat"}'::jsonb, 'The sounds are not placed in the order heard.', 'Offer "tam" beside "mat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say it slowly: first sound first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS.M1_BW_NO_VOWEL', 'ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS', 'Leaves out the vowel.', '{"question":"Make \"met\".","wrong_answer":"mt","correct_answer":"met"}'::jsonb, 'The vowel is not heard as a separate sound.', 'Offer "mt" beside "met" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every word needs a vowel: m-e-t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS.M1_BW_EXTRA', 'ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS', 'Adds an extra letter.', '{"question":"Make \"tea\".","wrong_answer":"teaa","correct_answer":"tea"}'::jsonb, 'The long sound is shown with more letters.', 'Offer "teaa" beside "tea" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tea: t-e-a.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS.M1_BW_A_E', 'ENGL.G1.READIN.T4_PRE_READING.BUILD_WORDS', 'Uses e for a or a for e.', '{"question":"Make \"mat\".","wrong_answer":"met","correct_answer":"mat"}'::jsonb, 'A and e are close for Kenyan learners.', 'Offer "met" beside "mat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Mat: mouth wide, a.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES.M1_PL_S_FOR_ES', 'ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES', 'Adds -s where -es is needed.', '{"question":"One box, two ...","wrong_answer":"boxs","correct_answer":"boxes"}'::jsonb, 'The -s rule is used for every noun.', 'Offer "boxs" beside "boxes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After x, s, ch and sh: -es.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES.M1_PL_NUMBER_NO_S', 'ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES', 'Leaves out -s after a number.', '{"question":"I have two ...","wrong_answer":"cup","correct_answer":"cups"}'::jsonb, 'The number already shows many, as in Kiswahili.', 'Offer "cup" beside "cups" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Two cups: keep the -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES.M1_PL_ES_ALL', 'ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES', 'Adds -es to every noun.', '{"question":"One cup, three ...","wrong_answer":"cupes","correct_answer":"cups"}'::jsonb, 'The -es rule is over-used once learnt.', 'Offer "cupes" beside "cups" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Most words take just -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES.M1_PL_A_CUPS', 'ENGL.G1.LANGUA.T4_SINGULAR_AND_PLURALS.PLURAL_S_ES', 'Puts -s on a noun after a.', '{"question":"I want a ...","wrong_answer":"cups","correct_answer":"cup"}'::jsonb, 'Plurals are over-used once learnt.', 'Offer "cups" beside "cup" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A means one: no -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P.M1_SL_S_SH', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P', 'Hears s as sh.', '{"question":"The teacher says \"sun\". Sun or shun?","wrong_answer":"shun","correct_answer":"sun"}'::jsonb, 'S and sh are not kept apart.', 'Offer "shun" beside "sun" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S: smile and hiss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P.M1_SL_L_R', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P', 'Hears l as r.', '{"question":"The teacher says \"leg\". Which letter: l or r?","wrong_answer":"r","correct_answer":"l"}'::jsonb, 'L and r merged.', 'Offer "r" beside "l" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'L: tongue up behind the teeth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P.M1_SL_PIN_PEN', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P', 'Hears pin and pen as the same.', '{"question":"The teacher says \"pin\". Pin or pen?","wrong_answer":"pen","correct_answer":"pin"}'::jsonb, 'One sound between e and i at home.', 'Offer "pen" beside "pin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pin: smile. Pen: mouth more open.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P.M1_SL_P_B', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.SOUNDS_S_L_I_P', 'Hears p as b.', '{"question":"The teacher says \"pot\". Pot or bot?","wrong_answer":"bot","correct_answer":"pot"}'::jsonb, 'Voice is not used to tell them apart.', 'Offer "bot" beside "pot" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'P puffs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL.M1_NV_EYES_DOWN', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL', 'Looks down the whole time when talking in class.', '{"question":"Talk to your partner about your family.","wrong_answer":"looks at the floor","correct_answer":"looks at the partner''s face now and then"}'::jsonb, 'Many Kenyan homes teach children to lower their eyes before elders; the child does the same with friends. To confirm by a teacher.', 'Offer "looks at the floor" beside "looks at the partner''s face now and then" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'With friends and in class, look at the person now and then.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL.M1_NV_FACE_MISMATCH', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL', 'Uses a face that does not fit the words.', '{"question":"Say sorry to a friend you bumped.","wrong_answer":"says sorry while laughing","correct_answer":"says sorry with a sorry face"}'::jsonb, 'The child is shy and laughs.', 'Offer "says sorry while laughing" beside "says sorry with a sorry face" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make your face match your words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL.M1_NV_NOD_MEANING', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL', 'Does not know what a nod or shake of the head means.', '{"question":"Your friend shakes her head. What does she mean?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Head gestures are not yet linked to meaning.', 'Offer "yes" beside "no" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Nod is yes; shake is no.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL.M1_NV_SHOUT', 'ENGL.G1.LISTEN.T5_PRONUNCIATION_AND_VO.NONVERBAL', 'Shouts in a quiet conversation.', '{"question":"Tell your partner your name.","wrong_answer":"shouts across the desk","correct_answer":"speaks in an indoor voice"}'::jsonb, 'Loud is thought to be clear.', 'Offer "shouts across the desk" beside "speaks in an indoor voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Partner talk: indoor voice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND.M1_ML_NAME', 'ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND', 'Matches by letter name, not sound.', '{"question":"Which letter makes the sound /s/ as in sun: c or s?","wrong_answer":"c (see)","correct_answer":"s"}'::jsonb, 'The name see sounds like /s/.', 'Offer "c (see)" beside "s" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'C says /k/; s says /s/.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND.M1_ML_I_E', 'ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND', 'Matches the i sound to e.', '{"question":"Which letter makes the sound in \"it\"?","wrong_answer":"e","correct_answer":"i"}'::jsonb, 'One sound between e and i at home.', 'Offer "e" beside "i" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It: smile, i.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND.M1_ML_P_B', 'ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND', 'Matches /p/ to b.', '{"question":"Which letter makes the sound in \"pot\"?","wrong_answer":"b","correct_answer":"p"}'::jsonb, 'Voice is not used to tell them apart.', 'Offer "b" beside "p" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'P puffs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND.M1_ML_L_R', 'ENGL.G1.READIN.T5_PRE_READING.MATCH_LETTER_SOUND', 'Matches /l/ to r.', '{"question":"Which letter makes the sound in \"leg\"?","wrong_answer":"r","correct_answer":"l"}'::jsonb, 'L and r merged.', 'Offer "r" beside "l" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up: l.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE.M1_PS_HE_NO_S', 'ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE', 'Leaves out -s after he or she.', '{"question":"Every day Mama ... water. (fetch)","wrong_answer":"fetch","correct_answer":"fetches"}'::jsonb, 'Kiswahili verbs do not change for he and she in this way.', 'Offer "fetch" beside "fetches" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'He or she: add -s or -es.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE.M1_PS_I_S', 'ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE', 'Adds -s after I.', '{"question":"I ... my teeth every morning. (brush)","wrong_answer":"brushes","correct_answer":"brush"}'::jsonb, 'The -s is over-used.', 'Offer "brushes" beside "brush" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I: no -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE.M1_PS_ING_ROUTINE', 'ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE', 'Uses the -ing form for a daily habit.', '{"question":"Every day I ... to school. (go)","wrong_answer":"am going","correct_answer":"go"}'::jsonb, 'Common Kenyan English uses -ing for habits.', 'Offer "am going" beside "go" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every day: I go.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE.M1_PS_ES_SPELL', 'ENGL.G1.LANGUA.T5_TENSE_PRESENT_SIMPLE.PRESENT_SIMPLE', 'Adds -s where -es is needed.', '{"question":"She ... the dishes. (wash)","wrong_answer":"washs","correct_answer":"washes"}'::jsonb, 'The -es rule is not known.', 'Offer "washs" beside "washes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After sh: -es.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O.M1_FH_F_P', 'ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O', 'Hears f as p.', '{"question":"The teacher says \"fan\". Fan or pan?","wrong_answer":"pan","correct_answer":"fan"}'::jsonb, 'Some home languages have no /f/, others no /p/.', 'Offer "pan" beside "fan" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'F: teeth on lip, blow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O.M1_FH_N_M', 'ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O', 'Mixes n and m.', '{"question":"The teacher says \"nose\". Which letter: n or m?","wrong_answer":"m","correct_answer":"n"}'::jsonb, 'Both are nose sounds.', 'Offer "m" beside "n" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'N: lips open, tongue up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O.M1_FH_POT_PORT', 'ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O', 'Hears short o and long or as the same.', '{"question":"Which word has the sound in \"door\": dog, ball, dot?","wrong_answer":"dog","correct_answer":"ball"}'::jsonb, 'One o sound at home.', 'Offer "dog" beside "ball" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ball and door are long; dog is short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O.M1_FH_O_NAME', 'ENGL.G1.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS_F_N_H_O', 'Hears short o as the letter name o.', '{"question":"Which word has the sound in \"hot\": home, dog, nose?","wrong_answer":"nose","correct_answer":"dog"}'::jsonb, 'The letter name is taken as the sound.', 'Offer "nose" beside "dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short o: quick, as in hot and dog.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS.M1_PC_NO_BE', 'ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS', 'Leaves out am, is or are.', '{"question":"Look! The dog ... running.","wrong_answer":"(nothing): The dog running.","correct_answer":"is"}'::jsonb, 'The small word is not heard.', 'Offer "(nothing): The dog running." beside "is" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Is before -ing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS.M1_PC_NO_ING', 'ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS', 'Leaves out -ing.', '{"question":"She is ... now. (cook)","wrong_answer":"cook","correct_answer":"cooking"}'::jsonb, 'The child adds is but forgets -ing.', 'Offer "cook" beside "cooking" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Is + -ing: is cooking.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS.M1_PC_SPELL', 'ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS', 'Spells the -ing word wrongly.', '{"question":"He is ... (run)","wrong_answer":"runing","correct_answer":"running"}'::jsonb, 'The doubling rule is not known.', 'Offer "runing" beside "running" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Run, running.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS.M1_PC_WRONG_BE', 'ENGL.G1.LANGUA.T6_1_TENSE_PRESENT_CONT.PRESENT_CONTINUOUS', 'Uses the wrong form of be.', '{"question":"I ... writing.","wrong_answer":"is","correct_answer":"am"}'::jsonb, 'Is is used for all.', 'Offer "is" beside "am" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I am writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC.M1_SV_NO_VOWEL', 'ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC', 'Leaves out the vowel.', '{"question":"Write: bed","wrong_answer":"bd","correct_answer":"bed"}'::jsonb, 'The vowel is not heard as a separate sound.', 'Offer "bd" beside "bed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say it slowly: b-e-d. Three sounds, three letters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC.M1_SV_A_E', 'ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC', 'Writes e for a or a for e.', '{"question":"Write: bag","wrong_answer":"beg","correct_answer":"bag"}'::jsonb, 'A and e are close for Kenyan learners.', 'Offer "beg" beside "bag" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Bag: mouth wide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC.M1_SV_END_VOWEL', 'ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC', 'Adds a vowel at the end.', '{"question":"Write: dog","wrong_answer":"dogi","correct_answer":"dog"}'::jsonb, 'Kiswahili words end in a vowel.', 'Offer "dogi" beside "dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Dog stops at g.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC.M1_SV_LETTER_NAME', 'ENGL.G1.WRITIN.T6_SPELLING.SPELL_CVC', 'Uses a letter name for a word.', '{"question":"Write: you","wrong_answer":"u","correct_answer":"you"}'::jsonb, 'The letter name sounds like the word (u, c, r).', 'Offer "u" beside "you" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write every letter: y-o-u.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G.M1_BG_B_D', 'ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G', 'Mixes b and d.', '{"question":"Which letter does \"bed\" start with: b or d?","wrong_answer":"d","correct_answer":"b"}'::jsonb, 'Mirror shapes.', 'Offer "d" beside "b" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make the bed: b first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G.M1_BG_R_L', 'ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G', 'Hears r as l.', '{"question":"The teacher says \"red\". Red or led?","wrong_answer":"led","correct_answer":"red"}'::jsonb, 'L and r merged.', 'Offer "led" beside "red" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Curl the tongue: red.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G.M1_BG_U_NAME', 'ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G', 'Hears short u as the letter name you.', '{"question":"Which word has the sound in \"cup\": cute, sun, use?","wrong_answer":"cute","correct_answer":"sun"}'::jsonb, 'The letter name is taken as the sound.', 'Offer "cute" beside "sun" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short u: uh, as in cup and sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G.M1_BG_G_K', 'ENGL.G1.LISTEN.T7_PRONUNCIATION_AND_VO.SOUNDS_B_R_U_G', 'Hears g as k.', '{"question":"The teacher says \"goat\". Goat or coat?","wrong_answer":"coat","correct_answer":"goat"}'::jsonb, 'Voice is not used to tell g from k.', 'Offer "coat" beside "goat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'G buzzes in the throat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS.M1_SW_SOUND_OUT', 'ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS', 'Sounds out a sight word letter by letter.', '{"question":"Read: the","wrong_answer":"t-h-e","correct_answer":"the"}'::jsonb, 'Every word is treated as one to sound out.', 'Offer "t-h-e" beside "the" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some words we know by sight: the.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS.M1_SW_WAS_SAW', 'ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS', 'Reads was as saw.', '{"question":"Read: It was hot.","wrong_answer":"It saw hot.","correct_answer":"It was hot."}'::jsonb, 'The letters are read from the wrong end.', 'Offer "It saw hot." beside "It was hot." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start at the left: w.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS.M1_SW_SAID', 'ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS', 'Reads said as sayed or sid.', '{"question":"Read: Mama said yes.","wrong_answer":"Mama sayed yes.","correct_answer":"Mama said yes."}'::jsonb, 'Said does not follow the rules.', 'Offer "Mama sayed yes." beside "Mama said yes." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Said sounds like sed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS.M1_SW_SWAP_SMALL', 'ENGL.G1.READIN.T7_WORD_READING.SIGHT_WORDS', 'Swaps one small word for another.', '{"question":"Read: I see the cat.","wrong_answer":"I see a cat.","correct_answer":"I see the cat."}'::jsonb, 'Small words are guessed.', 'Offer "I see a cat." beside "I see the cat." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the word: the.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED.M1_PA_NO_ED', 'ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED', 'Leaves out -ed for the past.', '{"question":"Yesterday I ... football. (play)","wrong_answer":"play","correct_answer":"played"}'::jsonb, 'The time word is not linked to the verb.', 'Offer "play" beside "played" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Yesterday: add -ed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED.M1_PA_SPELL', 'ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED', 'Spells -ed words as they sound.', '{"question":"Write: washed","wrong_answer":"washt","correct_answer":"washed"}'::jsonb, 'The ending sounds like t.', 'Offer "washt" beside "washed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It sounds like t but is spelt -ed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED.M1_PA_DID_ED', 'ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED', 'Adds did before the past verb.', '{"question":"Yesterday I ... my hands. (wash)","wrong_answer":"did washed","correct_answer":"washed"}'::jsonb, 'Did is added to show the past.', 'Offer "did washed" beside "washed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Just washed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED.M1_PA_GOED', 'ENGL.G1.LANGUA.T7_TENSE_SIMPLE_PAST_TE.PAST_ED', 'Adds -ed to go.', '{"question":"Yesterday we ... to the shop. (go)","wrong_answer":"goed","correct_answer":"went"}'::jsonb, 'The new -ed rule is used for every verb.', 'Offer "goed" beside "went" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Go is special: went.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS.M1_BD_B_D', 'ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS', 'Writes d for b or b for d.', '{"question":"Which word is right: bog, dog?","wrong_answer":"bog","correct_answer":"dog"}'::jsonb, 'Mirror shapes.', 'Offer "bog" beside "dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make the bed: d on the right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS.M1_BD_P_Q', 'ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS', 'Writes q for p.', '{"question":"Fill: _en (to write with)","wrong_answer":"qen","correct_answer":"pen"}'::jsonb, 'Mirror shapes.', 'Offer "qen" beside "pen" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'P has its stick on the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS.M1_BD_U_N', 'ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS', 'Writes n for u.', '{"question":"Fill: _p (not down)","wrong_answer":"np","correct_answer":"up"}'::jsonb, 'U and n are the same shape upside down.', 'Offer "np" beside "up" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'U is a cup that holds water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS.M1_BD_G_Q', 'ENGL.G1.WRITIN.T7_SPELLING.B_D_LETTERS', 'Writes q for g.', '{"question":"Fill: _oat (an animal)","wrong_answer":"qoat","correct_answer":"goat"}'::jsonb, 'G and q look alike.', 'Offer "qoat" beside "goat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'G has a hook; q has a straight tail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W.M1_KD_K_G', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W', 'Hears k as g.', '{"question":"The teacher says \"cap\". Cap or gap?","wrong_answer":"gap","correct_answer":"cap"}'::jsonb, 'Voice is not used to tell them apart.', 'Offer "gap" beside "cap" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'K: no buzz.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W.M1_KD_D_T', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W', 'Hears d as t.', '{"question":"The teacher says \"doll\". Which letter: d or t?","wrong_answer":"t","correct_answer":"d"}'::jsonb, 'Voice is not used to tell them apart.', 'Offer "t" beside "d" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'D buzzes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W.M1_KD_W_V', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W', 'Hears w as v.', '{"question":"The teacher says \"wet\". Wet or vet?","wrong_answer":"vet","correct_answer":"wet"}'::jsonb, 'Some speakers mix w and v.', 'Offer "vet" beside "wet" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'W: round lips. V: teeth on lip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W.M1_KD_C_K_DIFFERENT', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.SOUNDS_K_D_W', 'Thinks c and k must make different sounds.', '{"question":"Do \"cat\" and \"kite\" start with the same sound?","wrong_answer":"no","correct_answer":"yes"}'::jsonb, 'Different letters are expected to mean different sounds.', 'Offer "no" beside "yes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'C and k can both say /k/.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS.M1_TW_SAME_GROUP', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS', 'Picks a word from the same group but not the right one.', '{"question":"We see with our ...","wrong_answer":"ears","correct_answer":"eyes"}'::jsonb, 'The group (body parts) is known; the word is not.', 'Offer "ears" beside "eyes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What do we do with it? See: eyes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS.M1_TW_HOME_WORD', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS', 'Uses a Kiswahili word.', '{"question":"The person who leads our location is the ...","wrong_answer":"mzee","correct_answer":"chief"}'::jsonb, 'The home word comes first to mind.', 'Offer "mzee" beside "chief" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In English: chief.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS.M1_TW_PICTURE_NEAR', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS', 'Names something near the object in the picture.', '{"question":"Picture: a girl holding a phone. What is she holding?","wrong_answer":"girl","correct_answer":"a phone"}'::jsonb, 'The biggest thing in the picture is named.', 'Offer "girl" beside "a phone" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point at what is in her hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS.M1_TW_SOUND_ALIKE', 'ENGL.G1.LISTEN.T8_PRONUNCIATION_AND_VO.THEME_WORDS', 'Picks a word that sounds like the right one.', '{"question":"We wash our hands at the ...","wrong_answer":"top","correct_answer":"tap"}'::jsonb, 'Cup and cap, tap and top sound alike to the child.', 'Offer "top" beside "tap" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say it in the sentence: does it make sense?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD.M1_RA_GUESS', 'ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD', 'Guesses words from the first letter or picture.', '{"question":"Read: The hen is in the hut.","wrong_answer":"The hen is in the house.","correct_answer":"The hen is in the hut."}'::jsonb, 'Sight-word guessing.', 'Offer "The hen is in the house." beside "The hen is in the hut." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read every letter: h-u-t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD.M1_RA_SKIP', 'ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD', 'Skips small words.', '{"question":"Read: I go to school.","wrong_answer":"I go school.","correct_answer":"I go to school."}'::jsonb, 'Small words carry little meaning for the child.', 'Offer "I go school." beside "I go to school." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point under every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD.M1_RA_LONG_STOPS', 'ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD', 'Stops for a long time on every word.', '{"question":"Read: My cat is big.","wrong_answer":"long stop after each word","correct_answer":"My cat is big. (smooth)"}'::jsonb, 'Each word is decoded slowly.', 'Offer "long stop after each word" beside "My cat is big. (smooth)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read it twice: the second time smoother.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD.M1_RA_LOST_PLACE', 'ENGL.G1.READIN.T8_FLUENCY.READ_ALOUD', 'Loses the place and repeats a line.', '{"question":"Read the two lines.","wrong_answer":"reads line one twice","correct_answer":"reads line one, then line two"}'::jsonb, 'The finger is not used to keep the place.', 'Offer "reads line one twice" beside "reads line one, then line two" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep your finger under the line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING.M1_RF_FLAT', 'ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING', 'Reads in a flat voice.', '{"question":"Read: \"I am so happy!\" said Ali.","wrong_answer":"flat voice","correct_answer":"a happy voice"}'::jsonb, 'The child is busy with the words.', 'Offer "flat voice" beside "a happy voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'How does Ali feel? Say it like him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING.M1_RF_QUESTION', 'ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING', 'Reads a question like a statement.', '{"question":"Read: Is it hot?","wrong_answer":"voice falls","correct_answer":"voice rises"}'::jsonb, 'Questions at home are marked by a word.', 'Offer "voice falls" beside "voice rises" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The question mark says lift your voice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING.M1_RF_LOUD_ALL', 'ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING', 'Reads everything in a loud voice.', '{"question":"Read: The baby is sleeping. Be quiet.","wrong_answer":"shouts it","correct_answer":"soft voice"}'::jsonb, 'Loud is thought to be good reading.', 'Offer "shouts it" beside "soft voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match your voice to the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING.M1_RF_NO_STOP', 'ENGL.G1.READIN.T8_FLUENCY.READ_WITH_FEELING', 'Reads through full stops.', '{"question":"Read: I ran. I fell.","wrong_answer":"I ran I fell.","correct_answer":"I ran. (stop) I fell."}'::jsonb, 'Full stops are seen as dots.', 'Offer "I ran I fell." beside "I ran. (stop) I fell." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stop at the dot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES.M1_DM_THIS_MANY', 'ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES', 'Uses this for many things.', '{"question":"... are my shoes. (near)","wrong_answer":"This","correct_answer":"These"}'::jsonb, 'This is learnt first.', 'Offer "This" beside "These" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Many, near: these.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES.M1_DM_NEAR_FAR', 'ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES', 'Uses this for something far away.', '{"question":"... is a bird on that far tree.","wrong_answer":"This","correct_answer":"That"}'::jsonb, 'Near and far are not linked to the words.', 'Offer "This" beside "That" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Far: that.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES.M1_DM_THESE_ONE', 'ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES', 'Uses these for one thing.', '{"question":"... is my nose.","wrong_answer":"These","correct_answer":"This"}'::jsonb, 'These sounds like this.', 'Offer "These" beside "This" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One: this.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES.M1_DM_THEM', 'ENGL.G1.LANGUA.T8_DEMONSTRATIVES_THIS_.DEMONSTRATIVES', 'Uses them for those.', '{"question":"Look at ... cows.","wrong_answer":"them","correct_answer":"those"}'::jsonb, 'Common in spoken English.', 'Offer "them" beside "those" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Those cows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S.M1_KJ_Y_J', 'ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S', 'Hears y (yes) as j.', '{"question":"The teacher says \"yam\". Yam or jam?","wrong_answer":"jam","correct_answer":"yam"}'::jsonb, 'The y sound is close to j.', 'Offer "jam" beside "yam" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Y: tongue up, no stop: yes, yam.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S.M1_KJ_Y_NAME', 'ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S', 'Gives the letter name wye for the y sound.', '{"question":"What sound does y make in \"yes\"?","wrong_answer":"wye","correct_answer":"/j/ as at the start of yes"}'::jsonb, 'Letter names are learnt first.', 'Offer "wye" beside "/j/ as at the start of yes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The sound is short: y-y-yes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S.M1_KJ_L_R', 'ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S', 'Hears l as r.', '{"question":"The teacher says \"lamp\". Lamp or ramp?","wrong_answer":"ramp","correct_answer":"lamp"}'::jsonb, 'L and r merged.', 'Offer "ramp" beside "lamp" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up: lamp.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S.M1_KJ_S_Z', 'ENGL.G1.LISTEN.T9_PRONUNCIATION_AND_VO.SOUNDS_K_J_L_S', 'Hears s as z.', '{"question":"The teacher says \"sip\". Sip or zip?","wrong_answer":"zip","correct_answer":"sip"}'::jsonb, 'Voice is not used to tell them apart.', 'Offer "zip" beside "sip" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S hisses, z buzzes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS.M1_NN_PROPER_SMALL', 'ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS', 'Writes a special name with a small letter.', '{"question":"Which is right?","wrong_answer":"juma lives in nakuru.","correct_answer":"Juma lives in Nakuru."}'::jsonb, 'Only the start of a sentence is thought to need a capital.', 'Offer "juma lives in nakuru." beside "Juma lives in Nakuru." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Names of people and places: capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS.M1_NN_COMMON_CAPITAL', 'ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS', 'Gives a capital to a general name.', '{"question":"Which is right?","wrong_answer":"I have a Dog.","correct_answer":"I have a dog."}'::jsonb, 'Important words are given capitals.', 'Offer "I have a Dog." beside "I have a dog." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Dog is a general name: small letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS.M1_NN_ACTION', 'ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS', 'Picks an action word as a naming word.', '{"question":"Which word names a thing: run, ball, big?","wrong_answer":"run","correct_answer":"ball"}'::jsonb, 'Naming words and doing words are new.', 'Offer "run" beside "ball" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Can you touch it? Ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS.M1_NN_PEOPLE_ONLY', 'ENGL.G1.LANGUA.T9_NOUNS_COMMON_AND_PRO.NOUNS', 'Thinks only people have names.', '{"question":"Is \"school\" a naming word?","wrong_answer":"no","correct_answer":"yes, it names a place"}'::jsonb, 'Name is linked to people.', 'Offer "no" beside "yes, it names a place" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'People, things and places all have names.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP.M1_CF_NO_STOP', 'ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP', 'Leaves out the full stop.', '{"question":"Correct: I can run","wrong_answer":"I can run","correct_answer":"I can run."}'::jsonb, 'The end of the line is taken as the end.', 'Offer "I can run" beside "I can run." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every sentence ends with a full stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP.M1_CF_SMALL_START', 'ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP', 'Starts with a small letter.', '{"question":"Correct: my dog is big.","wrong_answer":"my dog is big.","correct_answer":"My dog is big."}'::jsonb, 'The capital is forgotten.', 'Offer "my dog is big." beside "My dog is big." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with a capital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP.M1_CF_LINE_END', 'ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP', 'Puts a full stop at the end of every line.', '{"question":"Where does the full stop go in a sentence on two lines?","wrong_answer":"at the end of each line","correct_answer":"at the end of the sentence"}'::jsonb, 'The line is taken as the sentence.', 'Offer "at the end of each line" beside "at the end of the sentence" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The full stop goes where the idea ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP.M1_CF_CAPS_ALL', 'ENGL.G1.WRITIN.T9_PUNCTUATION_CAPITAL_.CAPITALS_FULL_STOP', 'Writes capitals on many words.', '{"question":"Which is right?","wrong_answer":"My Dog Is Big.","correct_answer":"My dog is big."}'::jsonb, 'Capitals look neat.', 'Offer "My Dog Is Big." beside "My dog is big." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only the first word and names.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS.M1_VS_POOL_PULL', 'ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS', 'Hears long oo and short oo as the same.', '{"question":"The teacher says \"pool\". Pool or pull?","wrong_answer":"pull","correct_answer":"pool"}'::jsonb, 'One u sound at home.', 'Offer "pull" beside "pool" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pool is long.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS.M1_VS_EE_I', 'ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS', 'Hears long ee as short i.', '{"question":"The teacher says \"seat\". Seat or sit?","wrong_answer":"sit","correct_answer":"seat"}'::jsonb, 'One i sound at home.', 'Offer "sit" beside "seat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Seat is long, with a smile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS.M1_VS_OI_O', 'ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS', 'Hears oi as o.', '{"question":"The teacher says \"boy\". Which word has the same vowel: toy, top, too?","wrong_answer":"top","correct_answer":"toy"}'::jsonb, 'The glide is not heard.', 'Offer "top" beside "toy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Oi slides: o-ee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS.M1_VS_AY_E', 'ENGL.G1.LISTEN.T10_PRONUNCIATION_AND_VO.VOWEL_SOUNDS', 'Hears long a as e.', '{"question":"The teacher says \"day\". Which word has the same vowel: play, pen, pat?","wrong_answer":"pen","correct_answer":"play"}'::jsonb, 'One e sound at home.', 'Offer "pen" beside "play" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long a slides: e-ee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS.M1_PP_IN_ON', 'ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS', 'Uses in for on.', '{"question":"The cup is ... the table.","wrong_answer":"in","correct_answer":"on"}'::jsonb, 'Kiswahili kwenye covers in and on.', 'Offer "in" beside "on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'On top: on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS.M1_PP_UNDER_BEHIND', 'ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS', 'Uses under for behind.', '{"question":"The boy is ... the tree. (hidden at the back)","wrong_answer":"under","correct_answer":"behind"}'::jsonb, 'Position words are new.', 'Offer "under" beside "behind" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'At the back: behind.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS.M1_PP_BETWEEN_ONE', 'ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS', 'Uses between with one thing.', '{"question":"The cat is ... the chair. (next to it)","wrong_answer":"between","correct_answer":"beside (next to)"}'::jsonb, 'Between is used for any near place.', 'Offer "between" beside "beside (next to)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Between needs two things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS.M1_PP_IN_INSIDE', 'ENGL.G1.LANGUA.T10_SIMPLE_PREPOSITIONS_.PREPOSITIONS', 'Mixes inside and outside.', '{"question":"It is raining. Play ...","wrong_answer":"outside","correct_answer":"inside"}'::jsonb, 'The pair is learnt together.', 'Offer "outside" beside "inside" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Rain: stay inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK.M1_QM_FULL_STOP', 'ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK', 'Ends a question with a full stop.', '{"question":"Which mark: Can you swim","wrong_answer":".","correct_answer":"?"}'::jsonb, 'Full stops are used for every sentence.', 'Offer "." beside "?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Asking: question mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK.M1_QM_STATEMENT', 'ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK', 'Puts a question mark after a statement.', '{"question":"Which mark: I can swim","wrong_answer":"?","correct_answer":"."}'::jsonb, 'The new mark is over-used.', 'Offer "?" beside "." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Telling: full stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK.M1_QM_BACKWARD', 'ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK', 'Writes the question mark backwards.', '{"question":"Which question mark is right?","wrong_answer":"a backwards question mark","correct_answer":"?"}'::jsonb, 'Mirror shapes.', 'Offer "a backwards question mark" beside "?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The hook opens to the left, like a backwards c on top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK.M1_QM_NO_CAPITAL', 'ENGL.G1.WRITIN.T10_PUNCTUATION_CAPITAL_.QUESTION_MARK', 'Starts a question with a small letter.', '{"question":"Correct: may I go out?","wrong_answer":"may I go out?","correct_answer":"May I go out?"}'::jsonb, 'The capital is forgotten.', 'Offer "may I go out?" beside "May I go out?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Questions start with a capital too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH.M1_SC_SH_S', 'ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH', 'Hears sh as s.', '{"question":"The teacher says \"share\". Share or sare?","wrong_answer":"sare","correct_answer":"share"}'::jsonb, 'Some home languages have no sh.', 'Offer "sare" beside "share" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Round lips: shhh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH.M1_SC_CH_SH', 'ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH', 'Hears ch as sh.', '{"question":"The teacher says \"chair\". Chair or share?","wrong_answer":"share","correct_answer":"chair"}'::jsonb, 'Ch and sh are not kept apart.', 'Offer "share" beside "chair" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ch starts with a stop: t-sh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH.M1_SC_TH_T', 'ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH', 'Hears th (thank) as t.', '{"question":"The teacher says \"thin\". Thin or tin?","wrong_answer":"tin","correct_answer":"thin"}'::jsonb, 'Th is missing in most home languages.', 'Offer "tin" beside "thin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue between the teeth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH.M1_SC_THV_D', 'ENGL.G1.LISTEN.T11_PRONUNCIATION_AND_VO.SH_CH_TH', 'Hears th (this) as d.', '{"question":"The teacher says \"this\". This or dis?","wrong_answer":"dis","correct_answer":"this"}'::jsonb, 'The voiced th is heard as d.', 'Offer "dis" beside "this" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue between the teeth, buzz.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.PREDICT.M1_PR_DESCRIBE', 'ENGL.G1.READIN.T11_COMPREHENSION.PREDICT', 'Describes the picture instead of predicting.', '{"question":"Title: The Big Rain. Picture: dark clouds. What will happen?","wrong_answer":"There are clouds.","correct_answer":"It will rain."}'::jsonb, 'The child says what is seen.', 'Offer "There are clouds." beside "It will rain." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What will happen? Use will.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.PREDICT.M1_PR_NO_CLUE', 'ENGL.G1.READIN.T11_COMPREHENSION.PREDICT', 'Predicts with no link to the title or picture.', '{"question":"Title: My New Phone. What is the story about?","wrong_answer":"a cow","correct_answer":"a phone"}'::jsonb, 'The first idea is said.', 'Offer "a cow" beside "a phone" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the title and picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.PREDICT.M1_PR_ALREADY', 'ENGL.G1.READIN.T11_COMPREHENSION.PREDICT', 'Gives what has already happened.', '{"question":"The boy dropped his cup. What will happen next?","wrong_answer":"The boy dropped his cup.","correct_answer":"The cup will break, or he will pick it up."}'::jsonb, 'Next and before are mixed.', 'Offer "The boy dropped his cup." beside "The cup will break, or he will pick it up." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Next means after.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.PREDICT.M1_PR_AFRAID', 'ENGL.G1.READIN.T11_COMPREHENSION.PREDICT', 'Will not guess.', '{"question":"What do you think will happen?","wrong_answer":"I do not know.","correct_answer":"any sensible guess with a clue"}'::jsonb, 'Fear of being wrong.', 'Offer "I do not know." beside "any sensible guess with a clue" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Guess, then we check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS.M1_AQ_OWN_LIFE', 'ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS', 'Answers from home life.', '{"question":"Text: Tom has a red ball. What colour is Tom''s ball?","wrong_answer":"blue, like mine","correct_answer":"red"}'::jsonb, 'The child answers from home.', 'Offer "blue, like mine" beside "red" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What does the text say?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS.M1_AQ_WRONG_WORD', 'ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS', 'Gives the wrong kind of answer.', '{"question":"Text: The cat is under the bed. Where is the cat?","wrong_answer":"the cat","correct_answer":"under the bed"}'::jsonb, 'Question words are not matched to answers.', 'Offer "the cat" beside "under the bed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Where wants a place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS.M1_AQ_YES', 'ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS', 'Answers yes to every question.', '{"question":"Text: Ali has a dog. What does Ali have?","wrong_answer":"Yes.","correct_answer":"a dog"}'::jsonb, 'Every question is treated as yes or no.', 'Offer "Yes." beside "a dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What wants a thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS.M1_AQ_NOT_SAID', 'ENGL.G1.READIN.T11_COMPREHENSION.ANSWER_QUESTIONS', 'Says a feeling question cannot be answered.', '{"question":"Text: Amina cried. How did Amina feel?","wrong_answer":"It does not say.","correct_answer":"sad"}'::jsonb, 'Only the exact words are looked for.', 'Offer "It does not say." beside "sad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Crying shows sad.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES.M1_AJ_AFTER', 'ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES', 'Puts the describing word after the noun.', '{"question":"Say: (a red ball)","wrong_answer":"a ball red","correct_answer":"a red ball"}'::jsonb, 'Kiswahili puts it after (mpira mwekundu).', 'Offer "a ball red" beside "a red ball" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describing word first: a red ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES.M1_AJ_ACTION', 'ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES', 'Picks an action word as a describing word.', '{"question":"Which word describes: tall, jump, the?","wrong_answer":"jump","correct_answer":"tall"}'::jsonb, 'Describing words are new.', 'Offer "jump" beside "tall" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It tells what something is like: tall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES.M1_AJ_OPPOSITE', 'ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES', 'Uses the opposite describing word.', '{"question":"An elephant is very ...","wrong_answer":"small","correct_answer":"big"}'::jsonb, 'Pairs are learnt together.', 'Offer "small" beside "big" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Think of the elephant: big.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES.M1_AJ_PLURAL', 'ENGL.G1.LANGUA.T11_ADJECTIVES_ONE_AND_T.ADJECTIVES', 'Adds -s to the describing word.', '{"question":"Say: two (red) balls","wrong_answer":"two reds balls","correct_answer":"two red balls"}'::jsonb, 'Kiswahili adjectives change for plural.', 'Offer "two reds balls" beside "two red balls" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describing words never take -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK.M1_PT_ONE_THING', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK', 'Names one object instead of saying what the picture is about.', '{"question":"Picture: a chief talking to people. What is it about?","wrong_answer":"a hat","correct_answer":"The chief is talking to the people."}'::jsonb, 'The child names what stands out.', 'Offer "a hat" beside "The chief is talking to the people." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who is in it and what are they doing?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK.M1_PT_OWN_STORY', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK', 'Tells a story not in the picture.', '{"question":"Picture: children sharing food. What is happening?","wrong_answer":"We went to Mombasa.","correct_answer":"The children are sharing food."}'::jsonb, 'The picture sets off the child''s own memory.', 'Offer "We went to Mombasa." beside "The children are sharing food." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say only what you can see.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK.M1_PT_WRONG_ACTION', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK', 'Gives the wrong action or feeling.', '{"question":"Picture: a girl laughing. What is she doing?","wrong_answer":"crying","correct_answer":"laughing"}'::jsonb, 'Faces in pictures are not looked at closely.', 'Offer "crying" beside "laughing" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at her face.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK.M1_PT_HOME_WORD', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING.PICTURE_TALK', 'Names the picture in Kiswahili.', '{"question":"Picture: a market. What place is it?","wrong_answer":"soko","correct_answer":"a market"}'::jsonb, 'The home word comes first to mind.', 'Offer "soko" beside "a market" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In English: a market.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES.M1_WS_NO_SPACES', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES', 'Writes the words with no spaces.', '{"question":"Write: I like my school.","wrong_answer":"Ilikemyschool.","correct_answer":"I like my school."}'::jsonb, 'Speech has no gaps.', 'Offer "Ilikemyschool." beside "I like my school." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A finger space after each word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES.M1_WS_NO_VERB', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES', 'Writes a group of words with no verb.', '{"question":"Write a sentence about your friend.","wrong_answer":"My friend Amina.","correct_answer":"My friend is Amina."}'::jsonb, 'The child names the thing.', 'Offer "My friend Amina." beside "My friend is Amina." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add the doing or being word: is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES.M1_WS_NO_MARKS', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES', 'Leaves out the capital and full stop.', '{"question":"Write: we play ball","wrong_answer":"we play ball","correct_answer":"We play ball."}'::jsonb, 'Marks are forgotten while spelling.', 'Offer "we play ball" beside "We play ball." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Capital first, full stop last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES.M1_WS_COPY', 'ENGL.G1.WRITIN.T11_GUIDED_WRITING.WRITE_SIMPLE_SENTENCES', 'Copies the model sentence instead of writing a new one.', '{"question":"Write your own sentence about the picture.","wrong_answer":"copies the teacher''s sentence","correct_answer":"writes a new sentence"}'::jsonb, 'Copying is what writing has meant so far.', 'Offer "copies the teacher''s sentence" beside "writes a new sentence" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Change one word to make it yours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR.M1_EA_BED_BEAD', 'ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR', 'Hears short e and long ee as the same.', '{"question":"The teacher says \"bed\". Bed or bead?","wrong_answer":"bead","correct_answer":"bed"}'::jsonb, 'Vowel length is not heard.', 'Offer "bead" beside "bed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Bed is short; bead is long.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR.M1_EA_SHIP_SHEEP', 'ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR', 'Hears long ee as short i.', '{"question":"The teacher says \"sleep\". Sleep or slip?","wrong_answer":"slip","correct_answer":"sleep"}'::jsonb, 'One i sound.', 'Offer "slip" beside "sleep" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sleep is long.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR.M1_EA_HAIR_HEAR', 'ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR', 'Hears air as ear.', '{"question":"The teacher says \"chair\". Which word has the same sound: hair, hear, here?","wrong_answer":"hear","correct_answer":"hair"}'::jsonb, 'The two glides are close.', 'Offer "hear" beside "hair" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Air starts with e: chair, hair.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR.M1_EA_TWO_BEATS', 'ENGL.G1.LISTEN.T12_PRONUNCIATION_AND_VO.E_EE_AIR', 'Hears air as two beats (ai-ya).', '{"question":"Clap the beats in \"chair\".","wrong_answer":"2","correct_answer":"1"}'::jsonb, 'Each vowel letter is given a beat.', 'Offer "2" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Chair: one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES.M1_PO_HIS_HER', 'ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES', 'Uses his for a girl.', '{"question":"Amina has a pen. It is ... pen.","wrong_answer":"his","correct_answer":"her"}'::jsonb, 'Kiswahili yake serves both.', 'Offer "his" beside "her" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A girl: her.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES.M1_PO_ME', 'ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES', 'Uses me for my.', '{"question":"This is ... bag.","wrong_answer":"me","correct_answer":"my"}'::jsonb, 'Me and my are mixed.', 'Offer "me" beside "my" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Before a noun: my.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES.M1_PO_US', 'ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES', 'Uses us for our.', '{"question":"This is ... classroom.","wrong_answer":"us","correct_answer":"our"}'::jsonb, 'Us and our are mixed.', 'Offer "us" beside "our" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Our classroom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES.M1_PO_THEY', 'ENGL.G1.LANGUA.T12_POSSESSIVES_MY_OUR_H.POSSESSIVES', 'Uses they for their.', '{"question":"That is ... house.","wrong_answer":"they","correct_answer":"their"}'::jsonb, 'They and their are mixed.', 'Offer "they" beside "their" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Their house.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS.M1_FG_SOUND_ALIKE', 'ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS', 'Picks a word that sounds like the right one.', '{"question":"I drink tea from a ___ (cup, cap).","wrong_answer":"cap","correct_answer":"cup"}'::jsonb, 'Cup and cap sound alike to Kenyan learners.', 'Offer "cap" beside "cup" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read it: do you drink from a cap?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS.M1_FG_WRONG_KIND', 'ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS', 'Picks a word of the wrong kind.', '{"question":"The ___ is big. (dog, run)","wrong_answer":"run","correct_answer":"dog"}'::jsonb, 'Any known word is put in.', 'Offer "run" beside "dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the sentence with it: does it make sense?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS.M1_FG_FIRST', 'ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS', 'Always picks the first choice.', '{"question":"We ___ to school. (eat, walk)","wrong_answer":"eat","correct_answer":"walk"}'::jsonb, 'The child guesses without reading.', 'Offer "eat" beside "walk" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Try each word in the gap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS.M1_FG_A_PLURAL', 'ENGL.G1.WRITIN.T12_GUIDED_WRITING.FILL_GAPS', 'Puts a plural after a.', '{"question":"I have a ___ (cat, cats).","wrong_answer":"cats","correct_answer":"cat"}'::jsonb, 'A is not linked to one.', 'Offer "cats" beside "cat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A means one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY.M1_OA_BOOK_BOOT', 'ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY', 'Hears short oo (book) as long oo (boot).', '{"question":"Which word has the sound in \"book\": foot, food, boot?","wrong_answer":"food","correct_answer":"foot"}'::jsonb, 'The short oo is said long as the spelling looks.', 'Offer "food" beside "foot" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Book and foot are short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY.M1_OA_OO_U', 'ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY', 'Hears short oo as the u of cup.', '{"question":"Which word has the sound in \"put\": cut, foot, cap?","wrong_answer":"cut","correct_answer":"foot"}'::jsonb, 'The two short sounds are close.', 'Offer "cut" beside "foot" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put and foot: lips round.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY.M1_OA_AY_A', 'ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY', 'Hears long a as the short a of cat.', '{"question":"The teacher says \"game\". Game or gam?","wrong_answer":"gam","correct_answer":"game"}'::jsonb, 'One a sound at home.', 'Offer "gam" beside "game" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long a slides: game.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY.M1_OA_AY_E', 'ENGL.G1.LISTEN.T13_PRONUNCIATION_AND_VO.OO_AY', 'Hears long a as short e.', '{"question":"The teacher says \"late\". Late or let?","wrong_answer":"let","correct_answer":"late"}'::jsonb, 'One e sound.', 'Offer "let" beside "late" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Late slides: e-ee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT.M1_WC_LOOKS_LIKE', 'ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT', 'Picks a word that looks like the new word.', '{"question":"The baby is in the cot. A cot is ...","wrong_answer":"a cat","correct_answer":"a small bed for a baby"}'::jsonb, 'Letters are matched.', 'Offer "a cat" beside "a small bed for a baby" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Does it fit the sentence?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT.M1_WC_GIVE_UP', 'ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT', 'Says the word cannot be known.', '{"question":"The hen sat on her nest. A nest is ...","wrong_answer":"I do not know.","correct_answer":"a bird''s home"}'::jsonb, 'The child does not use clues.', 'Offer "I do not know." beside "a bird''s home" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the picture and the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT.M1_WC_PICTURE_ONLY', 'ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT', 'Uses only the picture.', '{"question":"Picture: a boy and a tap. \"The boy turned the tap off.\" Off means ...","wrong_answer":"water","correct_answer":"not running"}'::jsonb, 'The picture is used and the words are not.', 'Offer "water" beside "not running" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the words too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT.M1_WC_USUAL_MEANING', 'ENGL.G1.READIN.T13_COMPREHENSION.WORD_FROM_CONTEXT', 'Gives the usual meaning of a word with two meanings.', '{"question":"The bat hung in the cave. Here a bat is ...","wrong_answer":"a stick for hitting a ball","correct_answer":"an animal that flies at night"}'::jsonb, 'The meaning known best is used.', 'Offer "a stick for hitting a ball" beside "an animal that flies at night" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Which meaning fits the cave?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS.M1_YN_ONE_WORD', 'ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS', 'Answers only yes or no.', '{"question":"Can you ride a bicycle?","wrong_answer":"Yes.","correct_answer":"Yes, I can."}'::jsonb, 'One word answers it.', 'Offer "Yes." beside "Yes, I can." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Yes, I can. No, I cannot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS.M1_YN_CAN_ING', 'ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS', 'Uses -ing after can or will.', '{"question":"Can you ... ? (come)","wrong_answer":"coming","correct_answer":"come"}'::jsonb, 'The -ing form is over-used.', 'Offer "coming" beside "come" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After can: plain verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS.M1_YN_ORDER', 'ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS', 'Asks with the statement order.', '{"question":"Ask your friend if she can swim.","wrong_answer":"You can swim?","correct_answer":"Can you swim?"}'::jsonb, 'Questions at home are marked by the voice.', 'Offer "You can swim?" beside "Can you swim?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put can first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS.M1_YN_WRONG_HELPER', 'ENGL.G1.LANGUA.T13_YES_NO_QUESTIONS_WIT.YES_NO_QUESTIONS', 'Answers with a different helping word.', '{"question":"Will you come tomorrow?","wrong_answer":"Yes, I can.","correct_answer":"Yes, I will."}'::jsonb, 'Yes, I can is learnt as the one answer.', 'Offer "Yes, I can." beside "Yes, I will." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Answer with the word in the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER.M1_WO_AS_GIVEN', 'ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'Copies the words in the order given.', '{"question":"Order: ball / I / a / have","wrong_answer":"ball I a have","correct_answer":"I have a ball."}'::jsonb, 'The task is seen as copying.', 'Offer "ball I a have" beside "I have a ball." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who? Start there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER.M1_WO_ADJ_AFTER', 'ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'Puts the describing word after the noun.', '{"question":"Order: a / tree / tall / see / I","wrong_answer":"I see a tree tall.","correct_answer":"I see a tall tree."}'::jsonb, 'Kiswahili puts it after.', 'Offer "I see a tree tall." beside "I see a tall tree." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describing word before the noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER.M1_WO_CAPITAL', 'ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'Ignores the capital-letter clue.', '{"question":"Order: run / We / fast","wrong_answer":"run We fast","correct_answer":"We run fast."}'::jsonb, 'The capital is not seen as a clue.', 'Offer "run We fast" beside "We run fast." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The word with a capital comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER.M1_WO_VERB_FIRST', 'ENGL.G1.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'Puts the action first.', '{"question":"Order: sings / Mama","wrong_answer":"Sings Mama.","correct_answer":"Mama sings."}'::jsonb, 'The action is the most important word.', 'Offer "Sings Mama." beside "Mama sings." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who first, then what.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG.M1_JS_J_Y', 'ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG', 'Hears j as y.', '{"question":"The teacher says \"jam\". Jam or yam?","wrong_answer":"yam","correct_answer":"jam"}'::jsonb, 'The two sounds are close.', 'Offer "yam" beside "jam" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'J starts with a stop: d-zh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG.M1_JS_NG_G', 'ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG', 'Thinks a g is heard after ng.', '{"question":"In \"sing\", do you hear a g at the end?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Kenyan English often adds g after ng.', 'Offer "yes" beside "no" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ng is one nose sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG.M1_JS_NG_N', 'ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG', 'Hears ng as n.', '{"question":"The teacher says \"sing\". Sing or sin?","wrong_answer":"sin","correct_answer":"sing"}'::jsonb, 'Two nose sounds.', 'Offer "sin" beside "sing" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ng: back of the tongue up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG.M1_JS_S_SH', 'ENGL.G1.LISTEN.T14_PRONUNCIATION_AND_VO.J_S_NG', 'Hears s as sh.', '{"question":"The teacher says \"six\". Six or shix?","wrong_answer":"shix","correct_answer":"six"}'::jsonb, 'S and sh mixed.', 'Offer "shix" beside "six" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S: smile and hiss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE.M1_AP_HERE_THERE', 'ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE', 'Mixes here and there.', '{"question":"Come ... and sit by me.","wrong_answer":"there","correct_answer":"here"}'::jsonb, 'The pair is learnt together.', 'Offer "there" beside "here" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Near me: here.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE.M1_AP_INSIDE_OUTSIDE', 'ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE', 'Mixes inside and outside.', '{"question":"The goats sleep ... the shed.","wrong_answer":"outside","correct_answer":"inside"}'::jsonb, 'The pair is learnt together.', 'Offer "outside" beside "inside" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In the shed: inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE.M1_AP_UP_DOWN', 'ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE', 'Mixes up and down.', '{"question":"The cat climbed ... the tree.","wrong_answer":"down","correct_answer":"up"}'::jsonb, 'The pair is learnt together.', 'Offer "down" beside "up" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Climb up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE.M1_AP_NEAR_FAR', 'ENGL.G1.LANGUA.T14_ADVERBS_OF_PLACE.ADVERBS_PLACE', 'Mixes near and far.', '{"question":"The shop is ... We walk for one hour.","wrong_answer":"near","correct_answer":"far"}'::jsonb, 'The pair is learnt together.', 'Offer "near" beside "far" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A long walk: far.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R.M1_LR_L_R', 'ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R', 'Hears l as r.', '{"question":"The teacher says \"light\". Light or right?","wrong_answer":"right","correct_answer":"light"}'::jsonb, 'L and r merged.', 'Offer "right" beside "light" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up: light.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R.M1_LR_R_L', 'ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R', 'Hears r as l.', '{"question":"The teacher says \"rain\". Rain or lane?","wrong_answer":"lane","correct_answer":"rain"}'::jsonb, 'L and r merged.', 'Offer "lane" beside "rain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Curl the tongue: rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R.M1_LR_S_SH', 'ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R', 'Hears s as sh.', '{"question":"The teacher says \"save\". Save or shave?","wrong_answer":"shave","correct_answer":"save"}'::jsonb, 'S and sh mixed.', 'Offer "shave" beside "save" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S: smile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R.M1_LR_END_VOWEL', 'ENGL.G1.LISTEN.T15_PRONUNCIATION_AND_VO.L_S_R', 'Hears a vowel at the end of a word ending in s.', '{"question":"Clap the beats in \"bus\".","wrong_answer":"2 (ba-si)","correct_answer":"1"}'::jsonb, 'Kiswahili basi ends in a vowel and is carried over.', 'Offer "2 (ba-si)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Bus stops at s: one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS.M1_SU_SAD', 'ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS', 'Uses a sad word for surprise.', '{"question":"Your aunt visits without warning. You say \"...!\"","wrong_answer":"Oh no","correct_answer":"Oh! (or Wow!)"}'::jsonb, 'Interjections are learnt as a list.', 'Offer "Oh no" beside "Oh! (or Wow!)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Oh or Wow for surprise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS.M1_SU_NO_MARK', 'ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS', 'Leaves out the exclamation mark.', '{"question":"Write: Wow a big cake","wrong_answer":"Wow a big cake.","correct_answer":"Wow! A big cake!"}'::jsonb, 'The word is written as part of the sentence.', 'Offer "Wow a big cake." beside "Wow! A big cake!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'An exclamation mark after Wow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS.M1_SU_HOME_WORD', 'ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS', 'Uses a home-language word for surprise.', '{"question":"Say what you say when you see a big elephant.","wrong_answer":"Kumbe!","correct_answer":"Wow!"}'::jsonb, 'Everyday Kenyan exclamations are used at home.', 'Offer "Kumbe!" beside "Wow!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In English: Oh! Wow!', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS.M1_SU_OUCH', 'ENGL.G1.LANGUA.T15_INTERJECTIONS_OF_SUR.SURPRISE_WORDS', 'Uses a pain word for surprise.', '{"question":"You see a rainbow. You say \"...!\"","wrong_answer":"Ouch","correct_answer":"Wow"}'::jsonb, 'Ouch and wow are both said loudly.', 'Offer "Ouch" beside "Wow" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ouch is for pain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES.M1_DS_NONE', 'ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES', 'Writes a sentence with no describing word.', '{"question":"Write a sentence about the tree with a describing word.","wrong_answer":"I see a tree.","correct_answer":"I see a tall tree."}'::jsonb, 'The child writes the simplest sentence known.', 'Offer "I see a tree." beside "I see a tall tree." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add a word that tells what it is like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES.M1_DS_AFTER', 'ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES', 'Puts the describing word after the noun.', '{"question":"Write about the green leaf.","wrong_answer":"a leaf green","correct_answer":"a green leaf"}'::jsonb, 'Kiswahili order.', 'Offer "a leaf green" beside "a green leaf" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Green leaf.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES.M1_DS_LIST', 'ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES', 'Writes a list of describing words.', '{"question":"Write a sentence about the water.","wrong_answer":"clean, cold, nice","correct_answer":"The water is clean and cold."}'::jsonb, 'The child lists the words learnt.', 'Offer "clean, cold, nice" beside "The water is clean and cold." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put them in a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES.M1_DS_NICE', 'ENGL.G1.WRITIN.T15_GUIDED_WRITING.DESCRIBING_SENTENCES', 'Uses nice for everything.', '{"question":"Write about the river.","wrong_answer":"The river is nice.","correct_answer":"The river is clean and wide."}'::jsonb, 'Nice is the one safe word.', 'Offer "The river is nice." beside "The river is clean and wide." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What does it look like? Choose a sharper word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
